window.__SUPERCODE_LANG_PACKS__=window.__SUPERCODE_LANG_PACKS__||{};window.__SUPERCODE_LANG_PACKS__['ko']={"index":{"metaTitle":"안드로이드 코드 에디터 추천: SuperCode IDE — 오프라인 Python, C, C++, Java, JS, SQL, PHP 통합개발환경","metaDesc":"네이티브 안드로이드 오프라인 코드 에디터 및 풀스택 모바일 IDE. GB급 대용량 파일 편집, Python, C17, C++20, Java 17, JavaScript, Lua, Shell, SQL, 로컬 PHP/WASM 웹 서버와 비주얼 Git·SFTP를 하나의 앱에서 경험하세요.","hero_tag":"네이티브 오프라인 코드 에디터 &amp; 풀스택 모바일 IDE","hero_h1":"안드로이드를 위한 네이티브 <span class=\"text-gradient\">코드 에디터<\/span> &amp; 풀스택 IDE.","hero_desc":"소프트웨어 엔지니어, 컴퓨터공학 전공생, DevOps 팀을 위해 설계된 안드로이드 코드 에디터 추천 1순위 워크스테이션입니다. <strong>AST 문맥 인식 자동완성<\/strong>, <strong>GB급 대용량 파일 스트리밍<\/strong>, <strong>Python, C17, C++20, Java 17, JS, SQL, PHP, Lua, Shell<\/strong> 오프라인 컴파일·실행부터 비주얼 <strong>Git<\/strong>과 <strong>SFTP/FTPS<\/strong>까지 완벽히 통합했습니다.","table_h2":"안드로이드 개발 환경 정밀 비교","snippet_p":"<strong>SuperCode IDE<\/strong>는 안드로이드 코드 에디터 추천 분야에서 독보적인 네이티브 오프라인 풀스택 개발 환경입니다. AST 스마트 자동완성, GB급 대용량 파일 페이징, 30종 이상의 포매터는 물론 Python, C17, C++20, Java 17, JavaScript, SQL, PHP, HTML/CSS/WASM, Lua, Shell 오프라인 런타임과 비주얼 Git, SFTP/FTPS 클라이언트를 하나로 통합했습니다.","table_caption":"안드로이드 모바일 개발 환경 기능 비교 매트릭스","faq_lead":"오프라인 컴파일러, 대용량 파일 처리, 지원 언어 및 Git/SFTP 워크플로에 대해 자주 묻는 질문과 답변입니다.","cta_h2":"단 하나의 네이티브 앱. 내 손안의 14개 전문 엔지니어링 스튜디오.","cta_desc":"지금 Google Play에서 SuperCode IDE를 다운로드하고 안드로이드 기기에서 13단계 인터랙티브 투어를 직접 체험해 보세요.","th_0":"비교 항목","th_1":"SuperCode IDE","th_2":"클라우드 브라우저 IDE","th_3":"단일 언어 코딩 앱","th_4":"기본 텍스트 에디터","tr1_c0":"오프라인 지원 언어","tr1_c1":"Python, C17, C++20, Java 17, JS, SQL, PHP, Web/WASM, Lua, Shell","tr1_c2":"상시 인터넷 연결 필수","tr1_c3":"앱당 1개 언어만 지원","tr1_c4":"실행 불가","tr2_c0":"에디터 인텔리전스","tr2_c1":"AST 자동완성 + 듀얼 하이라이트 + 30+ 포매터 + 에러 레이더","tr2_c2":"네트워크 지연 발생","tr2_c3":"기본 키워드 색상만 제공","tr2_c4":"단순 텍스트 / 정규식 색상","tr3_c0":"대용량 파일 &amp; 치환","tr3_c1":"GB급 10MB 페이저 + 전역 스트림 정규식 치환 + 34종 인코딩","tr3_c2":"브라우저 탭 메모리 다운","tr3_c3":"수 MB 초과 시 멈춤/종료","tr3_c4":"대용량 로그 열기 시 먹통","tr4_c0":"웹 &amp; 데이터베이스","tr4_c1":"실제 로컬 HTTP + 오프라인 PHP + PDO SQLite + DevTools + .db 뷰어","tr4_c2":"유료 컨테이너 구독 필요","tr4_c3":"별도 앱 여러 개 설치 필요","tr4_c4":"정적 HTML 단순 보기만 지원","tr5_c0":"Git &amp; 원격 DevOps","tr5_c1":"비주얼 Git 타임머신 + 병합 UI + SFTP/FTPS AES-256 원자적 저장","tr5_c2":"클라우드 워크스페이스 한정","tr5_c3":"Git 및 SFTP 미지원","tr5_c4":"외부 클라이언트 앱 별도 필요","faq1_q":"SuperCode IDE에서 인터넷 없이 오프라인으로 실행 가능한 프로그래밍 언어는 무엇인가요?","faq1_a":"안드로이드 기기 로컬에서 Python(3.11 및 과학 연산용 3.12), C(GNU C17), C++(GNU C++20), Java 17, JavaScript(ES2024), SQL, 동적 PHP, HTML5/CSS3/WebAssembly, Lua 5.4, Linux Shell 스크립트를 100% 오프라인으로 실행할 수 있으며, Kotlin·MySQL 8.0·대규모 서버 프레임워크는 선택형 클라우드 실행도 지원합니다.","faq2_q":"수 기가바이트(GB) 크기의 대용량 로그 파일이나 SQL 덤프도 멈춤 없이 열 수 있나요?","faq2_a":"네. 30MB를 초과하는 파일은 자동으로 GB급 디스크 스트리밍 페이저가 작동하여 수백 MB~수 GB 파일을 1,000만 글자 단위의 디스크 청크로 분할 로드하며, 즉시 페이지 점프, EUC-KR 포함 34종 인코딩 자동 감지, 전역 스트림 정규식 치환을 지원합니다.","faq3_q":"C와 C++, 또는 SQL과 웹/PHP 환경이 각각 전용 워크스페이스로 분리되어 있나요?","faq3_a":"네. C17과 C++20은 각각의 전용 표준 플래그·헤더·템플릿으로 분리되어 있으며, SQL은 9가지 출력 모드와 원탭 .db 바이너리 탐색기를 갖추고 있고, 웹 스튜디오는 내장 DevTools가 결합된 실제 로컬 HTTP + PHP + PDO SQLite + WebAssembly 서버를 구동합니다.","faq4_q":"외부 터미널 설치 없이 Git 클라이언트와 SFTP/FTPS 원격 서버 편집을 바로 쓸 수 있나요?","faq4_a":"네. 자체 내장된 안드로이드 비주얼 Git 클라이언트(PAT 클론, 브랜치 관리, 커밋 타임머신 Diff, 병합 충돌 해결기)와 AES-256 암호화 SFTP·FTPS(TLS 1.3)·FTP 원격 워크스페이스(3단계 원자적 저장 지원)가 기본 탑재되어 있습니다.","faq5_q":"안드로이드 스마트폰과 태블릿 화면 모두에 최적화되어 있나요?","faq5_a":"네. 스마트폰에서는 한 손 엄지 반경에 맞춘 적응형 하단 툴바, 우측 엣지 스와이프 메뉴, 타이핑 시 자동 축소되는 분할 콘솔로 동작하며, 폴더블 및 태블릿 가로 모드에서는 세로 도킹 툴바와 55% : 45% 좌우 분할 워크스테이션 레이아웃으로 자동 전환됩니다.","wb_eyebrow":"Phoenix Global Studios · 14개 전용 엔지니어링 모듈 탑재","sec1_eyebrow":"13개 전용 엔지니어링 워크스페이스","sec1_title":"모든 언어, 데이터베이스, 원격 서버 도구 — 타협 없는 네이티브 설계","sec1_lead":"단 40.2 MB의 가벼운 안드로이드 앱 하나에 정밀하게 설계된 13개의 전문 개발 모듈을 모두 담았습니다.","bc1_title":"스마트 코드 에디터, AST 자동완성 &amp; 에러 레이더","bc1_desc":"., -&gt;, ::, : 연산자 기반 AST 문맥 자동완성, 듀얼 모드 구문 강조, 30종 이상의 오프라인 포매터, 실시간 에러 레이더 줄 이동, 홀로그램 통계, A4 PDF 내보내기와 29종 적응형 툴바를 제공합니다.","bc1_foot":"AST 자동완성 · 30+ 포매터 · 8종 스튜디오 테마","bc2_title":"GB급 대용량 파일 뷰어 &amp; 전역 스트림 정규식 치환","bc2_desc":"10MB 디스크 페이징으로 수백 MB~수 GB 로그 및 SQL 덤프를 120Hz로 즉시 열고, 전역 스트리밍 정규식 치환과 EUC-KR 포함 34종 문자 인코딩을 무손실로 처리합니다.","bc2_foot":"GB 페이저 · 스트림 치환 · 34종 인코딩","bc3_title":"전용 오프라인 GNU C17 컴파일러","bc3_desc":"&lt;math.h&gt;가 기본 링크되는 순수 GNU C17 표준 툴체인, 무설정 다중 .c/.h 자동 링킹, 포인터·구조체 예제 템플릿 및 실시간 대화형 scanf/fgets 입력을 지원합니다.","bc3_foot":"GNU C17 · 다중 .c/.h · 실시간 표준 입력","bc4_title":"Python 3.11 / 3.12 IDE &amp; 비주얼 PIP 패키지 매니저","bc4_desc":"안드로이드 파이썬 코딩 앱 오프라인 환경에서 다중 파일 프로젝트를 실행하고, PyPI·requirements.txt·로컬 .whl 패키지를 설치하며 NumPy/Pandas/Matplotlib 차트를 프로젝트 폴더에 즉시 생성합니다.","bc4_foot":"Python 3.11/3.12 · 자동 PIP · 데이터 사이언스","bc5_title":"모던 C++20 컴파일러 &amp; STL 알고리즘 IDE","bc5_desc":"다중 파일 C++20 STL, 템플릿, 스마트 포인터, 알고리즘 대회 코드를 증분 해시 캐시와 분할 화면 std::cin 콘솔로 오프라인에서 초고속 빌드합니다.","bc5_foot":"C++20 · STL 컨테이너 · 분할 입출력 콘솔","bc6_title":"오프라인 Java 17 IDE, 다중 클래스 OOP &amp; 내장 JDBC","bc6_desc":"Java 17 레코드, 봉인 클래스, 스트림, 다중 패키지 OOP 프로젝트를 0ms 바이트코드 캐시, 내장 SQLite JDBC 드라이버 및 커스텀 .jar 로드와 함께 오프라인으로 구동합니다.","bc6_foot":"Java 17 · 0ms 캐시 · 내장 SQLite JDBC","bc7_title":"독립형 JavaScript(ES2024) &amp; 다중 모듈 러너","bc7_desc":"UI 스레드와 완전히 분리된 워커 샌드박스에서 ES2024 async/await, ESM import/export, CommonJS 모듈을 실행하고 &lt;1ms 무한 루프 차단 및 클라우드 Node.js 번들링을 지원합니다.","bc7_foot":"ES2024 · ESM + CommonJS · 워커 샌드박스","bc8_title":"풀스택 웹, 로컬 PHP &amp; WASM 라이브 스튜디오","bc8_desc":"HTML5, CSS3, ES 모듈, WebAssembly(.wasm), 오프라인 동적 PHP + PDO SQLite DB, 모바일/태블릿/데스크톱 뷰포트 전환, DevTools JS REPL 및 SFTP 원격 프리뷰를 지원하는 실제 로컬 HTTP 서버입니다.","bc8_foot":"HTML/CSS/JS · WASM · 오프라인 PHP · DevTools","bc9_title":"오프라인 SQL IDE &amp; 비주얼 .db 데이터베이스 탐색기","bc9_desc":"윈도우 함수, 재귀 CTE, JSONB 경로, 전문 검색을 9가지 출력 모드로 오프라인 실행하고 원탭 .db/.sqlite 구조 탐색, CSV/JSON 임포트 및 클라우드 MySQL 8.0을 지원합니다.","bc9_foot":"오프라인 SQL · .db 탐색기 · CSV / JSON 임포트","bc10_title":"오프라인 Lua 5.4 스크립팅 &amp; 게임 로직 IDE","bc10_desc":"코루틴, 메타테이블, 비트 연산, 다중 파일 require() 및 대화형 io.read() 콘솔을 갖춘 마이크로초 단위의 네이티브 Lua 5.4.7 실행 환경입니다.","bc10_foot":"Lua 5.4.7 · 코루틴 · 다중 파일 모듈","bc11_title":"Linux Shell(.sh) 러너 &amp; Kotlin 스튜디오","bc11_desc":"프로젝트 폴더와 동기화되는 안드로이드 네이티브 리눅스 쉘 파이프라인(grep, awk, sed, sort, find) 실행과 클라우드 Ubuntu Bash 5.2 및 Kotlin 컴파일을 지원합니다.","bc11_foot":"네이티브 Shell · Bash 5.2 · Kotlin","bc12_title":"비주얼 Git 클라이언트, 타임머신 &amp; 병합 충돌 해결기","bc12_desc":"PAT 토큰 기반 HTTPS 저장소 클론, Pull 시 자동 Stash, 120개 커밋 컬러 통합 Diff 타임머신, 브랜치 전환 및 시각적 병합 충돌 해결 UI를 내장했습니다.","bc12_foot":"Git 클론 · 타임머신 Diff · 시각적 병합 UI","bc13_title":"SFTP, FTPS(TLS 1.3) &amp; FTP 원격 서버 워크스페이스","bc13_desc":"비밀번호 또는 Android KeyStore AES-256 금고에 암호화된 OpenSSH/PEM/Ed25519 개인키로 접속하세요. 0바이트 파일 손상을 원천 차단하는 3단계 원자적 원격 저장과 바이트 이어받기 4스트림 전송 큐를 제공합니다.","bc13_foot":"SFTP(22) · FTPS TLS 1.3 · SSH 키 금고 · 원자적 원격 저장","sec2_eyebrow":"한 손 터치 속도를 극대화한 인체공학 설계","sec2_title":"적응형 툴바부터 분할 터미널까지 빈틈없는 정밀함","sec2_lead":"모든 제스처, 심볼 키캡, 콘솔 패널이 스마트폰, 폴더블, 태블릿 가로 모드에 맞춰 자동으로 최적화됩니다.","keystrip_left":"21키 듀얼 액션 심볼 키보드 (6종 언어 프로필)","keystrip_right":"원탭 입력 · 스와이프 업 돋보기 · 커서 잠금 모드","craft_foot":"8종 광학 스튜디오 테마 + 주야간 자동 전환 · 32개 UI 언어 지원 · 태블릿 가로 듀얼 페인 콘솔","pil1_sub":"5단계 문맥 인식 적응형 툴바","pil1_title":"적응형 툴바, 우측 엣지 스와이프 &amp; 5개 퀵 슬롯","pil1_desc":"코드, 일반 텍스트, 영역 선택, 검색, 초대용량 파일 모드를 자동 전환하며 태블릿에서는 세로 도킹되고 120Hz 우측 엣지 스와이프 메뉴와 연동됩니다.","pil2_sub":"10MB 디스크 페이징 · 34종 인코딩","pil2_title":"초고속 대용량 파일 페이저 &amp; 스트리밍 정규식 치환","pil2_desc":"수 GB 서버 로그와 DB 덤프를 120Hz로 부드럽게 열고 디스크 청크 단위로 전역 정규식 치환을 수행하며 가상 클립보드로 최대 15MB까지 복사합니다.","pil3_sub":"비주얼 DIFF · AES-256 보안 금고","pil3_title":"실무형 버전 관리 &amp; 무손실 원자적 원격 동기화","pil3_desc":"로컬 오프라인 컴파일부터 비주얼 Git 충돌 해결, 3단계 원자적 SFTP/FTPS 실서버 배포까지 앱 하나로 끊김 없이 이어집니다."},"code_editor":{"metaTitle":"안드로이드 코드 에디터 추천 — 오프라인 AST 자동완성, 30+ 코드 포매터 & 에러 레이더 | SuperCode","metaDesc":"전문 개발자를 위한 네이티브 안드로이드 소스 코드 에디터. 오프라인 AST 스마트 자동완성, 40+ 확장자 듀얼 구문 강조, 30+ 언어 원탭 코드 정렬, 실시간 에러 레이더, UTF-8 바이트 통계, 29종 적응형 툴바와 8종 테마를 지원합니다.","hero_tag":"스마트 코드 에디터 &amp; AST 인텔리전스","hero_h1":"안드로이드 네이티브로 구현한 <span class=\"text-gradient\">AST 지능형 코드 에디터<\/span>.","hero_desc":"단순한 모바일 메모장을 넘어선 진짜 개발 도구입니다. 안드로이드 코드 에디터 추천 핵심 기준인 <strong>오프라인 AST 문맥 자동완성<\/strong>, <strong>듀얼 모드 구문 강조<\/strong>, <strong>30종 이상의 원탭 포매터<\/strong>, <strong>에러 레이더 정적 진단<\/strong>, 그리고 120Hz 터치에 최적화된 <strong>29종 적응형 툴바<\/strong>를 경험하세요.","table_h2":"SuperCode 에디터 vs 일반 모바일 텍스트 편집기","snippet_p":"<strong>SuperCode 스마트 코드 에디터<\/strong>는 오프라인 AST 문맥 인식 자동완성, 40종 이상의 듀얼 구문 강조, 30종 이상의 언어별 원탭 오프라인 포매터, 실시간 에러 레이더 정적 진단, 홀로그램 UTF-8 통계 및 29종 적응형 터치 툴바를 결합한 안드로이드 코드 에디터 추천 표준 앱입니다.","table_caption":"안드로이드 소스 코드 에디터 핵심 역량 비교","faq_lead":"오프라인 코드 정렬, 자동완성 지원 언어, 툴바 커스터마이징 및 PDF/이미지 뷰어에 대한 안내입니다.","cta_h2":"안드로이드에서 데스크톱급 코드 편집을 경험하세요.","cta_desc":"Google Play에서 SuperCode를 설치하고 8종 스튜디오 테마, 21키 심볼 바, 적응형 툴바를 나만의 스타일로 구성해 보세요.","th_0":"에디터 기능","th_1":"SuperCode 에디터","th_2":"WebView 래퍼형 에디터","th_3":"기본 안드로이드 메모 앱","tr1_c0":"스마트 자동완성","tr1_c1":"오프라인 AST 타입/멤버 추론 (., -&gt;, ::, :)","tr1_c2":"복잡한 플러그인 설정 또는 클라우드 LSP 필요","tr1_c3":"미지원 또는 단순 단어 목록","tr2_c0":"오프라인 코드 정렬","tr2_c1":"30종+ 파일 형식 + HTML/JS/CSS 재귀 정렬 + 선택 기준점 보존","tr2_c2":"JS/HTML/CSS 일부만 지원","tr2_c3":"미지원","tr3_c0":"구문 에러 실시간 검사","tr3_c1":"에러 레이더 V2.0 + 원탭 줄/열(Ln/Col) 점프","tr3_c2":"오프라인 미작동 또는 오탐 다수","tr3_c3":"미지원","tr4_c0":"모바일 터치 인체공학","tr4_c1":"29종 5모드 바 + 21키 스와이프 돋보기 + 우측 엣지 메뉴","tr4_c2":"비좁은 고정형 하단 버튼 줄","tr4_c3":"시스템 기본 키보드만 사용","tr5_c0":"클립보드 &amp; 문서 내보내기","tr5_c1":"15MB 가상 클립보드 + 네이티브 A4 PDF + 10종 이미지 뷰어","tr5_c2":"약 800KB 초과 시 시스템 클립보드 오류","tr5_c3":"단순 텍스트 공유만 가능","faq1_q":"스마트 코드 자동완성과 코드 포매터는 100% 오프라인으로 작동하나요?","faq1_a":"네. AST 문맥 인식 자동완성, 듀얼 모드 구문 강조, 실시간 에러 레이더 문법 검사, 30종 이상의 언어 포매터 모두 네트워크 연결 없이 안드로이드 기기 자체에서 100% 오프라인으로 즉시 실행됩니다.","faq2_q":"21키 심볼 키보드는 스마트폰 코딩 속도를 어떻게 높여주나요?","faq2_a":"현재 파일에 맞춰 6가지 언어 프로필(C/C++, Python, Java/Kotlin, JS/TS, Web, Shell/SQL)을 자동 로드하며, 선택 텍스트 괄호/따옴표 감싸기, 확대 돋보기가 표시되는 스와이프 업 보조 기호 입력, 코드 탐색 중 가상 키보드 팝업을 막아주는 커서 잠금 모드를 제공합니다.","faq3_q":"하단 툴바와 우측 퀵 메뉴 버튼 순서를 내 손에 맞게 바꿀 수 있나요?","faq3_a":"물론입니다. 설정 -&gt; 툴바 및 메뉴 사용자 지정에서 하단/측면 메인 툴바 아이콘 순서와 5개의 골든 퀵 액션 슬롯을 드래그하여 자유롭게 배치하거나 원탭으로 초기화할 수 있습니다.","faq4_q":"작성한 소스 코드를 PDF로 내보내거나 앱 안에서 PDF·이미지를 바로 볼 수 있나요?","faq4_a":"네. 인쇄 또는 .pdf로 다른 이름 저장을 통해 깔끔한 A4 고정폭 폰트 PDF를 생성할 수 있으며, 프로젝트 내 PDF(1x~5x 줌, 페이지 이동)와 10가지 이미지 포맷(WEBP, HEIC, AVIF, ICO 포함)을 외부 앱 없이 바로 확인할 수 있습니다.","wb_eyebrow":"인터랙티브 에디터 인텔리전스 데모","sec_cap_title":"실제 소프트웨어 프로젝트를 위해 툴바부터 새로 설계한 에디터","sec_cap_lead":"괄호 자동 건너뛰기부터 선택 영역 들여쓰기 보존 정렬까지, 모든 마이크로 인터랙션을 엄지 속도와 가독성에 맞춰 검증했습니다.","f1_title":"하이브리드 AST 문맥 인식 코드 자동완성","f1_desc":"C/C++, Python, Java, Kotlin, JS/TS, HTML, CSS, PHP, Lua, Shell, SQL에서 ., -&gt;, ::, : 입력 시 즉시 작동하여 로컬 변수 타입, 구조체·클래스 멤버, STL/DOM API 및 스니펫을 오프라인으로 추천합니다.","f1_badge":"연산자: . · -&gt; · :: · :  |  10개 언어 패밀리","f2_title":"듀얼 모드 구문 강조 &amp; 무확장자 파일 자동 판별","f2_desc":"현재 화면 영역을 120Hz로 즉시 렌더링하면서 문자열 내부 포맷 토큰(\\n, %d, {0})과 @param/TODO 태그까지 정밀하게 구분합니다. 확장자가 없는 파일도 #! 셔뱅(Shebang)과 어휘 분석으로 언어를 자동 인식합니다.","f2_badge":"40+ 확장자 · Shebang 스니퍼 · 0 프레임 드랍","f3_title":"30종+ 오프라인 코드 포매터 &amp; 스마트 주석기","f3_desc":"C/C++, Java, Kotlin, JS/TS, Python(PEP 8), JSON, CSS, PHP, SQL, Lua, Shell 및 HTML/Vue(내부 &lt;script&gt;·&lt;style&gt; 재귀 정렬 포함!)를 선택 영역 기준 들여쓰기를 유지한 채 단 한 번의 실행 취소(1-Undo) 단위로 깔끔하게 정렬합니다.","f3_badge":"단일 Undo 원자적 정렬 · HTML/JS/CSS 재귀 포맷","f4_title":"에러 레이더 V2.0 &amp; 홀로그램 UTF-8 문서 통계","f4_desc":"짝이 안 맞는 괄호, 닫히지 않은 문자열/태그, Python TabError 및 콜론 누락, 잘못된 JSON 쉼표를 즉시 포착해 원탭으로 해당 줄·열(Ln/Col)로 이동시키며, 전체 및 선택 영역의 줄·단어·글자·정확한 UTF-8 바이트 수를 함께 보여줍니다.","f4_badge":"원탭 Ln/Col 이동 · 전체 &amp; 선택 영역 UTF-8 바이트","f5_title":"29종 도구 5모드 적응형 툴바 &amp; 우측 엣지 스와이프 메뉴","f5_desc":"코드·일반 텍스트·선택·검색·초대용량 파일 5가지 모드로 자동 전환되며 가로 모드에서는 측면에 세로 도킹됩니다. 한 손으로 우측 화면 끝을 쓸어 열 수 있는 120Hz 스와이프 메뉴에는 창이 닫히지 않는 5개의 커스텀 퀵 슬롯이 제공됩니다.","f5_badge":"5종 자동 모드 · 5개 퀵 슬롯 · 15MB 가상 클립보드","f6_title":"21키 스와이프 업 심볼 바, 8종 광학 테마 &amp; A4 PDF 출력","f6_desc":"6가지 언어별 심볼 프로필을 자동 로드하며 탭 입력, 스와이프 업 확대 돋보기, 키보드 숨김 커서 잠금 모드를 지원합니다. 8종 WCAG AAA 광학 테마(주야간 자동 전환), 젠 모드 및 A4 고정폭 PDF 내보내기로 완성도를 높였습니다.","f6_badge":"6종 심볼 프로필 · AMOLED #000000 · 내장 PDF/이미지 뷰어","workflow_title":"나만의 모바일 코딩 워크스페이스 2분 완성 가이드","workflow_lead":"스마트폰과 태블릿 어디서나 데스크톱급 편집 흐름을 손쉽게 세팅하세요.","wf_foot_note":"상단 탭 드래그 순서 변경 지원 · 비정상 종료에도 미저장 탭을 보호하는 Hot Exit 자동 백업","wf1_title":"모든 소스 파일 열기 또는 새 스크래치패드 생성","wf1_desc":"내부 저장소, SD/USB OTG, Git, SFTP에서 다중 탭으로 파일을 여세요. 이름 없는 임시 탭도 문법을 자동 감지하여 스마트 저장 시 알맞은 확장자를 추천합니다.","wf2_title":"듀얼 액션 키캡과 AST 자동완성으로 고속 타이핑","wf2_desc":"탭하여 쌍괄호 삽입이나 선택 영역 감싸기를 수행하고, 키캡을 위로 밀어 보조 연산자(===, /**/, 내어쓰기) 입력과 0ms AST 멤버 자동완성을 활용하세요.","wf3_title":"원탭 코드 정렬 및 에러 레이더 좌표 점검","wf3_desc":"포맷 버튼으로 들여쓰기를 가지런히 정렬한 뒤 통계 버튼을 눌러 실시간 에러 레이더 위치와 선택 영역·전체 UTF-8 바이트 통계를 확인합니다.","wf4_title":"우측 화면 끝 스와이프로 5슬롯 연속 퀵 액션 실행","wf4_desc":"오른쪽 화면 가장자리를 안쪽으로 당겨 메뉴를 닫지 않고 실행 취소/다시 실행/테마/자동 줄바꿈을 연속 클릭하거나 젠 모드 전환 및 A4 PDF 내보내기를 실행하세요."},"large_file":{"metaTitle":"안드로이드 대용량 텍스트 로그 파일 뷰어 & EUC-KR 깨짐 해결 — GB 스트리밍 치환 | SuperCode","metaDesc":"안드로이드에서 수백 MB 및 수 GB 대용량 텍스트 로그 파일, SQL 덤프, CSV 데이터를 멈춤 없이 즉시 여세요. 10MB 디스크 페이징, 전역 스트리밍 정규식 치환, 15MB 가상 클립보드, EUC-KR 한글 깨짐을 방지하는 34종 인코딩을 지원합니다.","hero_tag":"GB급 대용량 파일 뷰어 &amp; 스트리밍 정규식 치환","hero_h1":"<span class=\"text-gradient\">GB급 대용량 로그 &amp; 덤프<\/span> 즉시 열기와 전역 스트림 치환.","hero_desc":"일반 모바일 편집기는 수 메가바이트만 넘어도 멈추거나 강제 종료됩니다. SuperCode는 대용량 텍스트 로그 파일 뷰어 EUC-KR 깨짐 문제를 완벽히 해결하며, 1,000만 자 디스크 페이징으로 <strong>수백 MB~수 GB 파일<\/strong>을 <strong>120Hz<\/strong>로 즉시 마운트하고 디스크 전체 <strong>스트리밍 정규식 일괄 치환<\/strong>과 <strong>34종 인코딩 무손실 디코딩<\/strong>을 수행합니다.","table_h2":"안드로이드 대용량 파일 &amp; 인코딩 처리 벤치마크","snippet_p":"<strong>SuperCode 대용량 파일 에디터<\/strong>는 안드로이드에서 수백 MB 및 기가바이트(GB) 규모의 텍스트, 서버 로그, CSV, SQL 파일을 멈춤 없이 즉시 여는 전문 뷰어 겸 편집기입니다. 1,000만 자 디스크 페이징, 전역 스트리밍 정규식 치환, 15MB 가상 클립보드와 EUC-KR을 포함한 34종 인코딩 무손실 자동 감지를 결합했습니다.","table_caption":"안드로이드 대용량 텍스트 &amp; 인코딩 엔진 비교 매트릭스","faq_lead":"GB급 파일 열기 원리, 정규식 일괄 치환, USB 메모리 연결 및 EUC-KR 한글 깨짐 복구에 대한 자주 묻는 질문입니다.","cta_h2":"거대 서버 로그, DB 덤프, EUC-KR 문서까지 멈춤 없이 여세요.","cta_desc":"Google Play에서 SuperCode IDE를 다운로드하고 120Hz GB급 텍스트·로그·코드 스튜디오를 활용하세요.","th_0":"핵심 역량","th_1":"SuperCode 메가 파일 엔진","th_2":"일반 모바일 코드 편집기","th_3":"시스템 기본 파일 뷰어","tr1_c0":"500MB – 2GB+ 파일 열기","tr1_c1":"즉각적인 10MB 디스크 페이징 + 1..N 페이지 점프","tr1_c2":"열기 시 메모리 부족으로 강제 종료","tr1_c3":"열기 거부 (2MB~10MB 제한)","tr2_c0":"전역 찾기 및 바꾸기","tr2_c1":"디스크 스트리밍 일괄 치환 + 정규식 $1..$99 그룹","tr2_c2":"RAM 한계 내 소규모 치환만 가능","tr2_c3":"읽기 전용 또는 치환 불가","tr3_c0":"초장문 압축 단일 행","tr3_c1":"자동 고속 기본 표시 (&gt;4,000자) · 멈춤 제로","tr3_c2":"압축된 JS/JSON에서 화면 먹통","tr3_c3":"자동 줄바꿈 계산 중 멈춤","tr4_c0":"대용량 복사 &amp; 붙여넣기","tr4_c1":"15MB 인프로세스 가상 클립보드 (10만 줄+)","tr4_c2":"약 800KB OS 제한에서 앱 종료","tr4_c3":"내용 잘림 또는 복사 실패","tr5_c0":"레거시 한글/다국어 인코딩","tr5_c1":"34종 인코딩(EUC-KR, GB18030, Shift_JIS, Win-125x) + UTF-8 가드","tr5_c2":"UTF-8 전용 (한글·한자·키릴 문자 깨짐)","tr5_c3":"인코딩 선택 기능 없음","faq1_q":"스마트폰 RAM 용량을 초과하는 1GB 이상의 파일을 어떻게 멈춤 없이 편집하나요?","faq1_a":"기가바이트 전체를 메모리에 한꺼번에 올리는 대신 파일을 약 1,000만 글자(~10MB) 단위의 디스크 기반 페이지 청크로 스트리밍 분할합니다. 화면에는 현재 활성 페이지만 상주하며, 전역 스트림 치환 역시 디스크 청크를 순차 처리하므로 메모리 부담 없이 안전합니다.","faq2_q":"EUC-KR 한글 깨짐이나 일본어·중국어·러시아어 레거시 인코딩 텍스트 파일도 복구할 수 있나요?","faq2_a":"네. 5단계 인코딩 자동 분석기가 EUC-KR, GB18030, GBK, Big5, Shift_JIS, EUC-JP, KOI8-R, Windows-1251/1252, BOM 없는 UTF-16 등 34종 문자셋을 정확히 식별하며, 원하는 인코딩으로 다시 읽거나 무손실로 UTF-8 변환 저장할 수 있습니다.","faq3_q":"한 줄 길이가 500KB에 달하는 압축(minified) JSON이나 JS 파일을 열면 어떻게 되나요?","faq3_a":"4,000자를 초과하는 초장문 행이 감지되면 자동으로 줄바꿈 연산을 생략하는 O(1) 고속 기본 표시 모드가 적용되어 압축 번들이나 긴 로그 라인도 끊김 없이 부드럽게 스크롤됩니다.","faq4_q":"USB 메모리(OTG)나 외장 SD 카드에 담긴 대용량 파일도 바로 열 수 있나요?","faq4_a":"네. 워크스페이스 탐색기에서 내부 저장소뿐만 아니라 외장 SD 카드와 핫플러그로 연결한 USB OTG 플래시 드라이브의 대용량 파일을 직접 열고 편집할 수 있습니다.","wb_eyebrow":"메가 파일 커맨드 센터 &amp; 디스크 스트림 엔진","sec_cap_title":"실서버 운영 로그, 대규모 DB 덤프, 레거시 한글 인코딩을 위한 설계","sec_cap_lead":"다계층 메모리 보호 설계를 통해 한 줄짜리 거대 압축 JSON이나 수 기가바이트 서버 로그에서도 스크롤, 검색, 저장이 쾌적하게 유지됩니다.","f1_title":"자동 GB급 10MB 디스크 페이징 스트리밍","f1_desc":"30MB가 넘는 파일은 백그라운드 I/O에서 자동으로 스트리밍 페이저가 가동되어 거대 로그, CSV, SQL 백업을 10,000,000자 페이지 단위로 분할하며, 4,000자 이상의 압축된 단일 행도 버벅임 없이 렌더링합니다.","f1_badge":"페이지당 1,000만 자 · 120Hz 스크롤 · 초장문 압축 행 안전 모드","f2_title":"메가 파일 커맨드 센터 &amp; 원자적 병합 저장","f2_desc":"이전 페이지, 다음 페이지 또는 1..N 페이지 직접 점프(이동 시 수정된 청크 자동 플러시)로 빠르게 탐색한 뒤 전체 병합 및 저장을 눌러 GB급 원본 파일을 디스크에서 원자적으로 안전하게 재결합합니다.","f2_badge":"페이지 [1/N] 즉시 점프 · 수정 청크 자동 보존 · 원자적 저장","f3_title":"전역 스트림 일괄 치환 &amp; 정규식 캡처 그룹","f3_desc":"파일 전체를 RAM에 올리지 않고도 디스크의 모든 페이지에 걸쳐 전역 스트림 모두 바꾸기를 실행합니다. $1..$99 및 ${name} 캡처 그룹, \\n/\\t 이스케이프, 선택 영역 한정 검색과 1,200ms 정규식 타임아웃 안전장치를 지원합니다.","f3_badge":"스트림 전체 치환 · 정규식 $1..$99 · 50,000+ 매치 버퍼","f4_title":"15MB 가상 메가 클립보드 (10만 줄 이상)","f4_desc":"안드로이드 기본 클립보드는 약 800KB 부근에서 오류를 일으킵니다. SuperCode의 인프로세스 가상 클립보드는 최대 15MB 분량의 로그나 SQL 구문을 탭 간에 손쉽게 복사, 잘라내기, 스트리밍 붙여넣기할 수 있습니다.","f4_badge":"800KB OS 한계 돌파 · 최대 15MB 대용량 붙여넣기","f5_title":"EUC-KR 포함 34종 문자 인코딩 &amp; 무손실 저장 가드","f5_desc":"UTF-8/16/32, EUC-KR, GB18030/GBK/Big5, Shift_JIS/EUC-JP, KOI8-R, ISO-8859 11종, Windows 코드 페이지 9종을 5단계로 자동 판별합니다. 저장 전 매핑 불가능한 유니코드 문자를 사전 경고하여 한글이 ?로 깨지는 사고를 원천 방지합니다.","f5_badge":"34종 인코딩 · BOM 안전 처리 · LF / CRLF / CR 보존","f6_title":"5만 파일 워크스페이스 퍼지 검색 &amp; 바이너리 방화벽","f6_desc":"로컬, Git, SD/USB OTG, SFTP 전반에서 7단계 CamelCase/경로 랭킹(node_modules·.git 자동 제외)으로 원하는 파일을 즉시 찾으며, 4KB 매직 바이트 검사로 비텍스트 바이너리 오열람을 안전하게 차단합니다.","f6_badge":"50,000 노드 스캔 · USB OTG 지원 · 4KB 매직 바이트 가드","workflow_title":"수백 MB ~ 수 GB 대용량 파일 탐색 및 일괄 편집 방법","workflow_lead":"안드로이드 스마트폰과 태블릿에서 거대 서버 로그, CSV 추출본, 레거시 인코딩 파일을 안전하게 다루세요.","wf_foot_note":"내부 저장소, 외장 SD 카드 및 핫플러그 USB OTG 외장 메모리 완벽 지원","wf1_title":"대용량 로그, CSV 또는 SQL 덤프 파일 열기","wf1_desc":"내부 저장소나 마운트된 SD 카드·USB OTG 드라이브에서 파일을 선택하면 인코딩을 자동 감지하고 1,000만 자 페이지를 즉시 마운트합니다.","wf2_title":"원하는 페이지 청크로 즉시 점프","wf2_desc":"간결한 7종 메가 파일 전용 바에서 페이지 버튼을 눌러 원하는 페이지 번호로 바로 이동하거나 텍스트 모드 및 젠 모드를 전환합니다.","wf3_title":"매치 탐색 또는 전역 스트림 모두 바꾸기 실행","wf3_desc":"검색창을 플로팅 미니 알약 바 형태로 접어둔 채 매치 지점을 순회하거나, 전역 스트림 모두 바꾸기로 디스크 전 구간 패턴을 일괄 변환합니다.","wf4_title":"변경 사항을 디스크에 원자적으로 확정 저장","wf4_desc":"전체 병합 및 저장을 탭하면 수정된 모든 청크가 문자 인코딩 무결성을 100% 유지한 채 원본 파일로 안전하게 병합 기록됩니다."},"python_ide":{"metaTitle":"안드로이드 파이썬 코딩 앱 오프라인 — Python 3.11/3.12 IDE, PIP, NumPy & Matplotlib | SuperCode","metaDesc":"인터넷 없이 실행되는 안드로이드 파이썬 코딩 앱 오프라인 개발 환경. 다중 파일 Python 3.11·3.12 실행, 비주얼 PIP 및 로컬 .whl 패키지 매니저, NumPy·Pandas·Matplotlib 차트 저장, 대화형 input()과 AST 자동완성을 지원합니다.","hero_tag":"오프라인 PYTHON 3.11 / 3.12 &amp; 비주얼 PIP 스튜디오","hero_h1":"안드로이드에서 <span class=\"text-gradient\">다중 파일 Python, PIP &amp; 데이터 사이언스<\/span>를 오프라인으로.","hero_desc":"스마트폰과 태블릿을 독립된 파이썬 워크스테이션으로 전환하세요. 안드로이드 파이썬 코딩 앱 오프라인 환경에서 <strong>다중 파일 Python 3.11 스크립트<\/strong>를 실행하고, <strong>Auto-PIP 및 로컬 .whl 패키지<\/strong>를 설치하며, <strong>NumPy, Pandas &amp; Matplotlib<\/strong> 그래프를 프로젝트 폴더에 바로 그려냅니다.","table_h2":"SuperCode Python IDE vs 타 안드로이드 파이썬 앱 비교","snippet_p":"<strong>SuperCode Python IDE<\/strong>는 다중 파일 스크립트 실행, 비주얼 PIP 및 로컬 .whl 패키지 매니저, 온디바이스 캐시 기반 NumPy·Pandas·Matplotlib 차트 생성, 실시간 대화형 input() 콘솔, PEP 8 포매터와 비주얼 Git/SFTP까지 통합한 안드로이드 파이썬 코딩 앱 오프라인 개발 스튜디오입니다.","table_caption":"안드로이드 PYTHON 개발 환경 정밀 비교","faq_lead":"오프라인 파이썬 실행, pip/.whl 라이브러리 설치, NumPy/Matplotlib 차트 저장 및 다중 파일 임포트 관련 FAQ입니다.","cta_h2":"오프라인에서도 멈추지 않는 모바일 Python 워크스테이션.","cta_desc":"Google Play에서 SuperCode IDE를 무료로 다운로드하고 40.2MB 앱 하나에 Python, PIP, NumPy, Git을 모두 담아 다니세요.","th_0":"Python 기능","th_1":"SuperCode Python IDE","th_2":"단독 파이썬 코딩 앱","th_3":"온라인 파이썬 러너","th_4":"터미널 에뮬레이터","tr1_c0":"오프라인 실행","tr1_c1":"Python 3.11 + 캐시된 과학 연산 3.12 오프라인 구동","tr1_c2":"기본 Python만 오프라인 지원","tr1_c3":"인터넷 연결 필수","tr1_c4":"수동 CLI 패키지 설치 필요","tr2_c0":"패키지 관리","tr2_c1":"Auto-PIP + requirements.txt + 로컬 .whl/.zip UI","tr2_c2":"유료 플러그인 또는 CLI pip","tr2_c3":"고정된 서버 패키지만 허용","tr2_c4":"네이티브 빌드 에러 빈발","tr3_c0":"데이터 분석 &amp; 차트","tr3_c1":"NumPy/Pandas/Matplotlib -&gt; 프로젝트 폴더 자동 저장","tr3_c2":"별도 구형 저장소 플러그인 필요","tr3_c3":"로컬 파일 동기화 불가","tr3_c4":"복잡한 X11/헤드리스 설정","tr4_c0":"다중 언어 &amp; Git 통합","tr4_c1":"C/C++, Java, JS, SQL, PHP, 비주얼 Git &amp; SFTP 포함","tr4_c2":"Python 단일 언어 전용","tr4_c3":"브라우저 샌드박스 한정","tr4_c4":"시각적 Git 병합 UI 없음","tr5_c0":"에디터 인텔리전스","tr5_c1":"AST 자동완성 + PEP 8 정렬 + 에러 레이더","tr5_c2":"기초적인 자동완성","tr5_c3":"네트워크 입력 지연","tr5_c4":"Vim/Nano 수동 설정 필수","faq1_q":"인터넷이 전혀 없는 비행기 모드에서도 안드로이드에서 파이썬 코드를 실행할 수 있나요?","faq1_a":"네. 다중 파일 Python 3.11 스크립트, 표준 라이브러리, 로컬에 설치된 PIP/.whl 패키지 및 캐시된 과학 연산용 Python 3.12 라이브러리(NumPy, Pandas, Matplotlib, SciPy, scikit-learn) 모두 100% 오프라인으로 실행됩니다.","faq2_q":"requests, bs4 같은 서드파티 라이브러리나 오프라인 .whl 파일은 어떻게 설치하나요?","faq2_a":"비주얼 PIP 패키지 매니저를 열거나 스크립트를 바로 실행해 Auto-PIP가 누락된 모듈을 자동 감지하도록 맡기세요. PyPI 온라인 설치, 감지된 requirements.txt 원탭 설치, 로컬 저장소의 .whl·.tar.gz·.zip 파일 반입을 모두 지원합니다.","faq3_q":"Matplotlib 그래프나 open('data.csv', 'w')로 생성한 파일은 어디에 저장되나요?","faq3_a":"스크립트가 생성하거나 수정한 모든 이미지, PDF, CSV, JSON 파일은 현재 열려 있는 프로젝트 폴더에 자동으로 동기화되며 SuperCode 내장 이미지 갤러리나 에디터 탭에서 즉시 열람할 수 있습니다.","faq4_q":"반복문 안의 대화형 input() 입력도 실시간으로 동작하나요?","faq4_a":"네. 스크립트가 input()을 호출할 때마다 분할 콘솔의 입력 바가 활성화되어 실행 흐름을 멈추고 사용자의 실시간 키보드 입력을 받아 이어서 동작합니다.","wb_eyebrow":"인터랙티브 PYTHON &amp; 데이터 사이언스 워크벤치","sec_cap_title":"순수 스크립트부터 데이터 분석까지 아우르는 3계층 Python 아키텍처","sec_cap_lead":"대학 전공 과제와 코딩 테스트부터 과학 데이터 시각화, 웹 스크래핑까지 복잡한 터미널 설정 없이 매끄럽게 동작합니다.","f1_title":"오프라인 다중 파일 Python 3.11 &amp; 스마트 진입점 라우팅","f1_desc":".py, .json, .csv, .yaml, .toml이 결합된 다중 모듈 프로젝트를 100% 오프라인으로 실행합니다. 보조 모듈 탭에서 실행 버튼을 눌러도 프로젝트의 메인 진입 스크립트를 자동으로 찾아 구동합니다.","f1_badge":"다중 파일 import · 미저장 탭 오버레이 · 파일 자동 동기화","f2_title":"온디바이스 캐시 기반 NumPy, Pandas &amp; Matplotlib","f2_desc":"numpy, scipy, pandas, matplotlib, scikit-learn 임포트 시 온디바이스 과학 연산 런타임이 작동하며 로컬에 캐시된 휠 패키지로 데이터 분석과 plt.savefig() 차트 생성을 오프라인으로 수행합니다.","f2_badge":"NumPy · Pandas · Matplotlib · PNG/SVG/PDF 자동 저장","f3_title":"비주얼 PIP 매니저, Auto-PIP &amp; 오프라인 .whl 임포트","f3_desc":"bs4나 yaml 같은 외부 모듈이 없나요? Auto-PIP가 별칭(bs4 -&gt; beautifulsoup4)을 자동 매핑해 PyPI에서 설치 후 스크립트를 재실행하며, requirements.txt 일괄 설치와 로컬 .whl/.zip 오프라인 반입도 지원합니다.","f3_badge":"Auto-PIP · requirements.txt · 오프라인 .whl 설치기","f4_title":"실시간 대화형 input() &amp; 크기 조절 분할 콘솔","f4_desc":"연속되는 여러 개의 input() 프롬프트에 실시간으로 값을 입력할 수 있습니다. 콘솔은 코드 하단에 깔끔하게 도킹(타이핑 시 자동 축소)되거나 태블릿 가로 모드에서 55%/45% 좌우 화면으로 열립니다.","f4_badge":"실시간 표준 입력 · ANSI 트루컬러 · 7sp–26sp 글꼴 확대","f5_title":"PEP 8 포매터, AST 자동완성 &amp; 에러 레이더","f5_desc":"21키 Python 전용 심볼 바, 오프라인 AST 멤버 자동완성, PEP 8 들여쓰기 자동 정렬과 더불어 실행 전 TabError 및 콜론(:) 누락을 즉시 잡아내는 에러 레이더로 깔끔한 코드를 작성하세요.","f5_badge":"PEP 8 자동 정렬 · TabError 가드 · 8종 입문/실전 템플릿","f6_title":"PyTorch, TensorFlow &amp; OpenCV 선택형 클라우드 클러스터","f6_desc":"무거운 딥러닝 프레임워크(torch, tensorflow, keras, cv2)나 # @cloud 실행이 필요할 때는 로컬 다중 모듈을 자동으로 번들링하여 에디터 줄 번호와 1:1로 일치하는 트레이스백 결과를 반환합니다.","f6_badge":"PyTorch · TensorFlow · OpenCV · 1:1 줄 번호 트레이스백","workflow_title":"SuperCode에서 Python 코딩 및 패키지 관리하는 방법","workflow_lead":"빈 폴더에서 단 네 번의 탭으로 다중 파일 Python 및 Matplotlib 시각화 프로젝트를 완성하세요.","wf_foot_note":"120초 CPU 워치독 보호 · 250KB 출력 폭주 차단 · 영구 패키지 디스크 매니저 내장","wf1_title":"스크립트 생성 또는 내장 Python 예제 불러오기","wf1_desc":"Python 전용 21키 심볼 바로 처음부터 작성하거나 코드 예제 라이브러리의 8가지 내장 Python 템플릿으로 빠르게 시작합니다.","wf2_title":"PyPI 라이브러리 또는 오프라인 .whl 아카이브 설치","wf2_desc":"감지된 requirements.txt 칩을 원탭으로 일괄 설치하고, 추천 패키지(requests, rich, bs4, flask)를 선택하거나 다운로드 폴더의 .whl 파일을 오프라인으로 불러옵니다.","wf3_title":"오프라인 실행 및 실시간 input() 상호작용","wf3_desc":"분할 화면 콘솔에서 출력 결과, 종료 코드, 밀리초 실행 시간, 메모리 변화량을 확인하며 input() 프롬프트에 실시간으로 응답을 입력합니다.","wf4_title":"생성된 차트 이미지, CSV &amp; JSON 결과 확인","wf4_desc":"open()이나 plt.savefig('plot.png')로 저장한 모든 파일이 프로젝트 폴더에 즉시 동기화되며 내장 고해상도 이미지·PDF 뷰어에서 바로 열립니다."},"c_compiler":{"metaTitle":"모바일 C언어 컴파일러 — 안드로이드 오프라인 GNU C17 IDE, 포인터 & 다중 파일 | SuperCode","metaDesc":"안드로이드를 위한 전용 오프라인 모바일 C언어 컴파일러 및 C17 IDE. Makefile 없이 다중 .c/.h 프로젝트를 빌드하고, 포인터와 구조체 실습, 실시간 대화형 scanf/fgets 입력 및 오프라인 C 코드 정렬을 경험하세요.","hero_tag":"전용 오프라인 GNU C17 컴파일러","hero_h1":"시스템 프로그래밍과 전공 실습을 위한 <span class=\"text-gradient\">전용 오프라인 C17 컴파일러<\/span>.","hero_desc":"C++ 런타임 오버헤드와 완전히 분리된 순수 모바일 C언어 컴파일러입니다. 별도 빌드 설정 없는 <strong>다중 파일 <code>.c/.h<\/code> 자동 링킹<\/strong>, <strong><code>&lt;math.h&gt;<\/code><\/strong> 기본 연결, 실시간 <strong><code>scanf<\/code> / <code>fgets<\/code> 표준 입력<\/strong>, 마이크로초 실행 텔레메트리와 함께 <strong>GNU C17(<code>-std=gnu17<\/code>)<\/strong> 코드를 오프라인에서 컴파일하세요.","table_h2":"SuperCode C17 컴파일러 vs 기존 모바일 C 컴파일 앱","snippet_p":"<strong>SuperCode 모바일 C언어 컴파일러<\/strong>는 안드로이드 전용 오프라인 GNU C17 통합개발환경입니다. 수학 라이브러리 자동 링킹이 적용된 순수 C17 컴파일, Makefile 없는 다중 .c/.h 프로젝트 자동 빌드, 실시간 대화형 scanf/fgets 입력, 파일 입출력 동기화 및 AST 구조체 자동완성을 제공합니다.","table_caption":"안드로이드 C 프로그래밍 컴파일러 비교","faq_lead":"안드로이드 오프라인 C17 컴파일, 다중 헤더 파일 링크, &lt;math.h&gt; 및 실시간 scanf 입력에 대한 답변입니다.","cta_h2":"언제 어디서나 안드로이드에서 C 언어를 마스터하세요.","cta_desc":"Google Play에서 SuperCode IDE를 설치하고 전용 오프라인 GNU C17 컴파일러와 다중 파일 워크스페이스를 바로 사용하세요.","th_0":"C 언어 기능","th_1":"SuperCode C17 스튜디오","th_2":"C/C++ 혼합형 간이 앱","th_3":"온라인 C 컴파일러","th_4":"CLI 터미널 직접 구축","tr1_c0":"C 표준 및 링크","tr1_c1":"전용 GNU C17 (-std=gnu17) + -lm 자동 링크","tr1_c2":".c 파일을 강제로 C++로 컴파일","tr1_c3":"외부 서버 연결 의존","tr1_c4":"수동 gcc 플래그 입력","tr2_c0":"다중 파일 .c / .h","tr2_c1":"무설정 자동 탐색 + 파일 해시 증분 캐시","tr2_c2":"단일 main.c 파일만 실행 가능","tr2_c3":"파일마다 수동 업로드","tr2_c4":"Makefile 직접 작성 필수","tr3_c0":"대화형 표준 입력","tr3_c1":"실시간 스트리밍 scanf / fgets + [EOF] 제어","tr3_c2":"실행 전 입력창 일괄 기입만 지원","tr3_c3":"사전 일괄 입력만 가능","tr3_c4":"지원됨","tr4_c0":"무한 루프 보호","tr4_c1":"15초 CPU 워치독 + 250K 출력 폭주 차단","tr4_c2":"while(1) 발생 시 앱 먹통","tr4_c3":"서버 타임아웃 에러","tr4_c4":"수동 Ctrl+C 강제 종료","tr5_c0":"에디터 &amp; Git 도구","tr5_c1":"AST -&gt;/. 자동완성 + C 포매터 + 비주얼 Git","tr5_c2":"단순 텍스트 입력창","tr5_c3":"브라우저 텍스트 상자","tr5_c4":"터치 친화적 GUI 없음","faq1_q":"SuperCode의 C 컴파일러는 C++ 컴파일러와 완전히 분리되어 있나요?","faq1_a":"네. .c 확장자 파일을 열면 C++ 모드로 우회 컴파일하지 않고 전용 GNU C17(-std=gnu17) 콘솔과 순수 C 표준 라이브러리가 활성화되어 정확한 C 언어 동작을 보장합니다.","faq2_q":"여러 개의 .c 파일과 .h 헤더를 컴파일할 때 Makefile을 만들어야 하나요?","faq2_a":"필요 없습니다. SuperCode가 프로젝트 폴더와 열린 탭의 #include \"...\" 헤더 및 연관 .c 파일들을 자동으로 스캔해 증분 컴파일하고 &lt;math.h&gt;(-lm)까지 자동으로 링크합니다.","faq3_q":"안드로이드에서 scanf()와 fgets() 대화형 입력이 실제로 작동하나요?","faq3_a":"네. C 프로그램이 표준 입력을 요청할 때마다 분할 터미널이 대기 상태로 전환되어 여러 줄의 데이터를 실시간으로 입력할 수 있으며, 빈 프롬프트 전송으로 EOF도 손쉽게 보낼 수 있습니다.","faq4_q":"코드에 &lt;pthread.h&gt;나 &lt;sys/socket.h&gt; 같은 리눅스 POSIX 헤더가 포함되어 있으면 어떻게 되나요?","faq4_a":"OS/POSIX 전용 헤더가 감지되면 다중 파일 프로젝트를 자동으로 POSIX 클라우드 C 툴체인으로 라우팅하여 컴파일하며, 에러 발생 시에도 로컬 파일명과 정확한 줄 번호를 그대로 표시해 줍니다.","wb_eyebrow":"전용 GNU C17 컴파일러 워크벤치","sec_cap_title":"C 프로그래머에게 C++와 분리된 전용 C17 아키텍처가 중요한 이유","sec_cap_lead":"대학 전공 실험, 임베디드 프로토타이핑, 자료구조 구현을 위해 정확한 C17 문법 규칙과 무설정 다중 파일 링킹을 제공합니다.","f1_title":"순수 GNU C17 표준 &amp; &lt;math.h&gt; 기본 링크","f1_desc":"C++ 네임 맹글링이나 불필요한 런타임 없이 -std=gnu17 플래그와 순수 C 표준 라이브러리 및 수학 라이브러리(-lm)로 엄격하게 컴파일하여 ANSI/ISO C 학부 과제와 시스템 기초 학습에 완벽히 부합합니다.","f1_badge":"-std=gnu17 · &lt;stdio.h&gt; · &lt;stdlib.h&gt; · &lt;math.h&gt;","f2_title":"무설정 다중 파일 .c / .h 자동 링커 &amp; 해시 캐시","f2_desc":"폴더와 열린 탭에서 #include \"...\" 로컬 헤더와 동반 .c 파일들을 자동 탐색하므로 Makefile 작성이 필요 없습니다. 증분 해시 캐시가 수정되지 않은 .c 번역 단위의 재컴파일을 생략해 빌드 속도를 극대화합니다.","f2_badge":"자동 .c/.h 탐색 · 헤더 -&gt; main.c 자동 라우팅","f3_title":"실시간 대화형 scanf / fgets / getchar 콘솔","f3_desc":"대화형 C 프로그램을 자연스럽게 테스트하세요. scanf나 fgets가 입력을 기다릴 때 터미널 입력창이 강조되며, 빈 줄을 전송하면 [EOF] 시그널이 전달되어 while(scanf(...) != EOF) 루프도 깔끔하게 종료됩니다.","f3_badge":"실시간 Stdin · [EOF] 시그널 · 마이크로초 + KB 통계","f4_title":"fopen / fwrite 워크스페이스 파일 I/O 자동 동기화","f4_desc":"fopen(), fprintf(), fwrite()로 기록한 텍스트 및 바이너리 파일이 프로젝트 폴더로 즉시 동기화되고 탐색기 트리가 자동 갱신되어 생성된 결과 파일을 바로 열어볼 수 있습니다.","f4_badge":"실제 파일 입출력 · 워크스페이스 트리 자동 동기화","f5_title":"무한 루프 서킷 브레이커 &amp; 포인터 진단","f5_desc":"실수로 작성한 while(1) 무한 루프나 폭주하는 printf도 걱정 없습니다. 유휴 시간 인지형 15초 CPU 워치독과 25만 자 출력 차단기가 스마트폰 멈춤 없이 프로세스를 안전하게 종료합니다.","f5_badge":"15초 워치독 · 250K 출력 차단기 · 정확한 줄 진단","f6_title":"6종 내장 C 핵심 템플릿 &amp; POSIX 클라우드 폴백","f6_desc":"포인터와 메모리, 구조체, 비트 연산, 사인파 생성, 표준 입력 에코 등 6가지 엄선된 C 예제로 학습을 시작하고, &lt;pthread.h&gt;, &lt;sys/socket.h&gt;, fork 등 POSIX 전용 헤더 사용 시 클라우드 C 툴체인과 매끄럽게 연동됩니다.","f6_badge":"6종 C 템플릿 · C 코드 포매터 · POSIX 클라우드 지원","workflow_title":"안드로이드에서 다중 파일 C 프로그램 빌드 및 디버깅하기","workflow_lead":"복잡한 빌드 스크립트 없이 단일 파일 연습 문제부터 다중 모듈 C 프로젝트까지 즉시 컴파일하세요.","wf_foot_note":"최초 1회 오프라인 툴체인 초기화 후 영구 오프라인 구동 · 파일별 증분 빌드 캐시","wf1_title":".c 소스 및 .h 헤더 파일 작성","wf1_desc":"C/C++ 전용 21키 심볼 바(-&gt;, *, &amp;, {}, ;, #include)와 AST 구조체 멤버 자동완성을 활용해 모듈화된 C17 코드를 작성합니다.","wf2_title":"전처리기 지시문 검사 및 오프라인 코드 정렬","wf2_desc":"에러 레이더가 잘못된 #include 구문과 괄호 불일치를 즉시 잡아내며, 포맷 버튼 한 번으로 K&amp;R/Allman 블록과 매크로 들여쓰기를 정렬합니다.","wf3_title":"어떤 프로젝트 탭에서든 오프라인 컴파일 &amp; 링크","wf3_desc":"커서가 utils.h 헤더 안에 있어도 실행을 누르면 자동으로 main.c를 찾아 수정된 파일만 증분 컴파일하고 -lm을 링크해 바이너리를 구동합니다.","wf4_title":"실시간 scanf 값 입력 및 출력 파일 확인","wf4_desc":"하단 또는 좌우 분할 터미널에 테스트 입력값을 실시간으로 넣고 종료 코드, 실행 시간(ms), 메모리 사용량 및 생성 파일을 확인합니다."},"cpp_ide":{"metaTitle":"안드로이드 C++20 IDE & 오프라인 C++ 컴파일러 — STL 알고리즘 코딩 테스트 & 다중 파일 | SuperCode","metaDesc":"안드로이드에서 모던 C++20을 오프라인으로 컴파일하고 실행하세요. 전체 STL 컨테이너·알고리즘, 해시 캐시 기반 다중 파일 .cpp/.hpp 빌드, AST std:: 자동완성, 실시간 std::cin 분할 콘솔과 8종 템플릿을 갖춘 안드로이드 C++20 IDE입니다.","hero_tag":"모던 오프라인 C++20 &amp; STL 알고리즘 스튜디오","hero_h1":"알고리즘 대회와 OOP 설계를 위한 <span class=\"text-gradient\">오프라인 C++20 &amp; STL IDE<\/span>.","hero_desc":"백준·코드포스·릿코드 그래프 알고리즘 풀이부터 다중 클래스 객체지향 아키텍처까지 완벽히 소화하는 안드로이드 C++20 IDE입니다. <strong>전체 STL<\/strong>, <strong>AST <code>std::<\/code> 자동완성<\/strong>, 반응형 <strong>분할 화면 <code>std::cin<\/code> 콘솔<\/strong>과 함께 <strong>GNU C++20(<code>-std=gnu++2a<\/code>)<\/strong>을 오프라인으로 빌드하세요.","table_h2":"SuperCode C++20 IDE vs 타 모바일 C++ 앱 비교","snippet_p":"<strong>SuperCode 안드로이드 C++20 IDE<\/strong>는 전체 STL 컨테이너 및 알고리즘, 증분 해시 캐시 기반 무설정 다중 파일 .cpp/.hpp 컴파일, 오프라인 AST std:: 자동완성, 실시간 std::cin 분할 터미널과 내장 비주얼 Git을 하나로 결합한 네이티브 오프라인 GNU C++20 개발 스튜디오입니다.","table_caption":"안드로이드 C++20 컴파일러 &amp; IDE 벤치마크","faq_lead":"C++20 오프라인 지원, STL 코딩 테스트 활용, 다중 헤더 파일 연결 및 멀티스레드에 관한 답변입니다.","cta_h2":"스마트폰과 태블릿에서 모던 C++20을 오프라인으로 빌드하세요.","cta_desc":"Google Play에서 SuperCode IDE를 다운로드하고 C++20 STL 컴파일, AST 자동완성, 비주얼 Git을 한 번에 활용하세요.","th_0":"C++ 핵심 역량","th_1":"SuperCode C++20 IDE","th_2":"구형 모바일 C++ 앱","th_3":"웹 기반 C++ 샌드박스","th_4":"터미널 CLI 컴파일러","tr1_c0":"지원 언어 표준","tr1_c1":"모던 GNU C++20 (-std=gnu++2a) 오프라인","tr1_c2":"구형 C++11/14 또는 무거운 추가 플러그인","tr1_c3":"인터넷 연결 필수","tr1_c4":"수동 CLI 패키지 구축 필요","tr2_c0":"다중 파일 OOP 빌드","tr2_c1":"자동 .cpp/.hpp 링커 + 증분 해시 캐시","tr2_c2":"단일 파일 한정 또는 수동 프로젝트 설정","tr2_c3":"단일 파일 복사·붙여넣기","tr2_c4":"수동 CMake/Makefile 작성","tr3_c0":"코드 인텔리전스","tr3_c1":"오프라인 AST std:: / -&gt; / :: 자동완성 + 포매터","tr3_c2":"단순 키워드 색상 표시","tr3_c3":"네트워크 지연 발생","tr3_c4":"외부 LSP 수동 구성 필요","tr4_c0":"분할 터미널 UX","tr4_c1":"세로 자동 축소 + 가로 55:45 분할 + ms/KB 측정","tr4_c2":"전체 화면 강제 전환","tr4_c3":"모바일에 비좁은 화면","tr4_c4":"멀티 탭 에디터 UI 없음","tr5_c0":"버전 관리 연동","tr5_c1":"내장 비주얼 Git Diff, 브랜치 &amp; 충돌 해결 UI","tr5_c2":"미지원","tr5_c3":"미지원","tr5_c4":"CLI git 명령어만 지원","faq1_q":"인터넷 없이 오프라인에서 C++20 문법과 STL 컨테이너를 모두 컴파일할 수 있나요?","faq1_a":"네. 첫 실행 시 오프라인 C++ 툴체인 팩이 한 번 초기화된 이후에는 GNU C++20(-std=gnu++2a)과 전체 STL(vector, map, priority_queue, ranges, 스마트 포인터, 람다 등)이 100% 오프라인으로 컴파일 및 실행됩니다.","faq2_q":"스마트폰이나 태블릿으로 백준, 코드포스, 릿코드 같은 알고리즘 대회 준비에 적합한가요?","faq2_a":"매우 적합합니다. 증분 캐시를 통한 빠른 재컴파일, 여러 줄의 테스트 케이스를 바로 붙여넣는 실시간 std::cin, 밀리초(ms)·킬로바이트(KB) 실행 측정치, 태블릿 55%/45% 좌우 분할 화면 덕분에 이동 중에도 쾌적하게 문제를 풀 수 있습니다.","faq3_q":"여러 개의 .cpp 파일과 .hpp 헤더로 나뉜 프로젝트는 어떻게 실행하나요?","faq3_a":"같은 프로젝트 폴더(또는 열린 에디터 탭)에 .hpp와 .cpp 파일들을 두기만 하면 됩니다. SuperCode가 로컬 include를 자동 분석해 모든 구현 파일을 링크하며, 헤더 탭에서 실행을 눌러도 main() 함수를 스스로 찾아 구동합니다.","faq4_q":"C++ &lt;thread&gt; 멀티스레딩이나 소켓 네트워크 API도 테스트할 수 있나요?","faq4_a":"네. OS 레벨 스레드나 소켓 헤더가 감지되면 다중 파일 프로젝트를 -pthread 옵션이 지원되는 클라우드 C++ 클러스터로 자동 연결해 컴파일하고 실행해 줍니다.","wb_eyebrow":"인터랙티브 C++20 &amp; STL 워크벤치","sec_cap_title":"알고리즘 대회 참가자, 컴퓨터공학도, C++ 엔지니어를 위한 정밀 설계","sec_cap_lead":"불편한 모바일 자판, 느린 온라인 채점 대기열, 번거로운 CMake 설정 없이 모던 C++20 코드에만 집중하세요.","f1_title":"완전한 오프라인 C++20 표준 라이브러리(STL)","f1_desc":"std::vector, map, unordered_map, set, priority_queue, string_view, optional, unique_ptr/shared_ptr, std::ranges::sort, 람다, 템플릿을 인터넷 연결 없이 오프라인으로 완벽히 컴파일합니다.","f1_badge":"-std=gnu++2a · STL 컨테이너 · Ranges &amp; 템플릿","f2_title":"std::, -&gt;, :: 심층 AST 멤버 자동완성","f2_desc":"v. 또는 ptr-&gt; 또는 std::를 입력하는 즉시 STL 컨테이너, 반복자, 스트림, 스마트 포인터 및 직접 작성한 클래스의 메서드와 멤버를 오프라인에서 즉시 추천합니다.","f2_badge":"AST 타입 추론 · 21키 C++ 전용 심볼 프로필","f3_title":"다중 파일 .cpp / .hpp 빌더 &amp; 해시 캐싱","f3_desc":"하위 폴더의 .cpp, .cc, .cxx, .hpp, .hh, .hxx, .inl 파일들을 자동 연결합니다. 수정되지 않은 소스 파일은 콘텐츠 해시로 캐싱되어 반복 빌드 시간을 획기적으로 단축합니다.","f3_badge":"다중 파일 OOP · 헤더 -&gt; main.cpp 자동 실행","f4_title":"코딩 테스트 맞춤형 분할 콘솔 &amp; 실시간 std::cin","f4_desc":"여러 줄로 된 대회 예제 입력을 실시간 std::cin에 바로 붙여넣고 정확한 실행 시간(ms)과 피크 메모리(KB)를 점검하세요. 태블릿 가로 모드에서는 55%/45% 좌우 워크스테이션으로 전환됩니다.","f4_badge":"고속 입출력 · 타이핑 시 자동 축소 · 정밀 텔레메트리","f5_title":"ofstream 파일 동기화 &amp; 무한 재귀/루프 보호","f5_desc":"std::ofstream으로 출력한 파일은 프로젝트 트리에 즉시 동기화되며, 15초 CPU 워치독과 25만 자 출력 제한기가 무한 재귀나 루프로부터 작업 중인 코드를 안전하게 보호합니다.","f5_badge":"ofstream 자동 동기화 · 15초 워치독 · 8종 C++ 템플릿","f6_title":"멀티스레드 클라우드 C++ 매끄러운 확장","f6_desc":"&lt;thread&gt;, std::async 또는 POSIX 소켓 API를 사용 중인가요? 다중 파일 소스를 -pthread가 활성화된 클라우드 C++ 클러스터로 자동 라우팅하고 1:1 줄 번호 진단을 반환합니다.","f6_badge":"&lt;thread&gt; 지원 · 에디터 1:1 줄 번호 진단","workflow_title":"안드로이드에서 알고리즘 문제 풀이 및 C++ 프로젝트 빌드하기","workflow_lead":"빠른 코딩 테스트 검증과 깔끔한 대학 다중 클래스 과제 수행에 최적화된 워크플로입니다.","wf_foot_note":".cpp · .cc · .cxx · .hpp · .hh · .hxx · .h · .inl 전체 확장자 완벽 지원","wf1_title":"내장 템플릿 또는 다중 파일 폴더로 시작","wf1_desc":"8가지 내장 C++ 알고리즘·OOP 예제를 열거나 로컬/Git 폴더 안에 헤더(.hpp)와 구현부(.cpp)를 체계적으로 구성합니다.","wf2_title":":: 및 -&gt; 전용 키캡으로 초고속 STL 코딩","wf2_desc":"C++ 전용 심볼 키로 ::, -&gt;, &lt;&lt;, &gt;&gt;, {}, &lt;&gt; 기호를 원탭 입력하면서 오프라인 AST STL 멤버 자동완성을 즉시 호출합니다.","wf3_title":"오프라인 고속 컴파일 &amp; 테스트 케이스 입력","wf3_desc":"실행을 눌러 밀리초 단위로 빌드한 뒤 std::cin에 샘플 테스트 케이스를 붙여넣고 실행 시간(ms)과 메모리 사용량(KB)을 검증합니다.","wf4_title":"코드 원탭 정렬 후 GitHub 저장소에 즉시 푸시","wf4_desc":"완성한 C++20 풀이를 원탭 포매터로 깔끔하게 정렬한 뒤 내장 비주얼 Git 클라이언트로 알고리즘 저장소에 바로 커밋·푸시합니다."},"java_ide":{"metaTitle":"모바일 자바 17 컴파일러 — 안드로이드 오프라인 Java 17 IDE, OOP & SQLite JDBC | SuperCode","metaDesc":"안드로이드에서 오프라인으로 컴파일하고 실행하는 모바일 자바 17 컴파일러 및 IDE. 레코드, 봉인 클래스, 스트림, 다중 클래스 OOP 패키지, 0ms 바이트코드 캐시, 내장 SQLite JDBC, 외부 .jar 라이브러리와 실시간 Scanner 입력을 지원합니다.","hero_tag":"오프라인 JAVA 17 · 다중 클래스 OOP &amp; 내장 JDBC","hero_h1":"안드로이드 오프라인에서 <span class=\"text-gradient\">Java 17 &amp; 다중 클래스 OOP<\/span> 컴파일 및 실행.","hero_desc":"대학 자바 전공 강의, 백엔드 프로토타이핑, 기술 면접 준비를 위해 탄생한 모바일 자바 17 컴파일러입니다. <strong>Java 17 레코드, 봉인 클래스 &amp; Stream API<\/strong>를 오프라인으로 작성하고 <strong>0ms 바이트코드 캐시 재실행<\/strong>, <strong>내장 SQLite JDBC<\/strong>, 실시간 <strong><code>Scanner(System.in)<\/code><\/strong>을 바로 활용하세요.","table_h2":"SuperCode Java 17 IDE vs 구형 안드로이드 자바 컴파일러","snippet_p":"<strong>SuperCode 모바일 자바 17 컴파일러<\/strong>는 안드로이드에서 모던 Java 17 레코드, 봉인 클래스, switch 표현식, Stream, 간결한 void main(), 0ms 캐시 재실행, 내장 오프라인 SQLite JDBC, 외부 .jar 로드 및 대화형 Scanner(System.in) 콘솔을 지원하는 다중 클래스 OOP 개발 워크스페이스입니다.","table_caption":"안드로이드 JAVA IDE &amp; 컴파일러 기능 비교","faq_lead":"오프라인 Java 17 문법 지원, 다중 파일 OOP, 외부 .jar 라이브러리 및 Scanner 입력에 대한 자주 묻는 질문입니다.","cta_h2":"안드로이드 어디서나 모던 Java 17을 작성하고 실행하세요.","cta_desc":"Google Play에서 SuperCode IDE를 다운로드하고 오프라인 Java 17, SQLite JDBC, AST 자동완성, 비주얼 Git을 경험하세요.","th_0":"Java 핵심 기능","th_1":"SuperCode Java 17 IDE","th_2":"구형 모바일 Java 앱","th_3":"온라인 Java 컴파일러","th_4":"원격 데스크톱 IDE","tr1_c0":"지원 Java 버전","tr1_c1":"오프라인 Java 17 + 클라우드 Java 21+","tr1_c2":"구형 Java 7 또는 Java 8에 정체","tr1_c3":"인터넷 연결 필수","tr1_c4":"원격 PC 상시 구동 필요","tr2_c0":"다중 클래스 &amp; .jar","tr2_c1":"다중 패키지 자동 실행 + libs/*.jar + 캐시","tr2_c2":"메인 클래스 수동 지정 번거로움","tr2_c3":"단일 파일 붙여넣기 한정","tr2_c4":"무거운 Gradle 빌드 대기","tr3_c0":"데이터베이스 연결","tr3_c1":"오프라인 jdbc:sqlite 드라이버 기본 내장","tr3_c2":"미포함","tr3_c3":"일회성 메모리 세션만 유지","tr3_c4":"수동 Maven 의존성 설정","tr4_c0":"학습자 편의성","tr4_c1":"간결한 void main() + 깔끔한 스택 트레이스","tr4_c2":"장황한 보일러플레이트 강제","tr4_c3":"오프라인 학습 불가","tr4_c4":"모바일 터치 비최적화","tr5_c0":"통합 개발 워크플로","tr5_c1":"Java + SQL 탐색기 + 비주얼 Git + SFTP 통합","tr5_c2":"Java 단독 샌드박스","tr5_c3":"브라우저 탭 한정","tr5_c4":"배터리 및 데이터 소모 큼","faq1_q":"안드로이드 오프라인 상태에서 컴파일 가능한 Java 버전은 무엇인가요?","faq1_a":"레코드(record), 봉인 클래스(sealed), switch 화살표 표현식, instanceof 패턴 매칭, 텍스트 블록, Stream API를 포함한 Java 17을 오프라인으로 컴파일 및 실행하며, Java 21+ 기능은 자동으로 클라우드 Java로 연결됩니다.","faq2_q":"여러 개의 클래스와 패키지로 나뉜 Java 프로젝트도 실행할 수 있나요?","faq2_a":"네. 프로젝트 폴더와 열린 에디터 탭에 있는 모든 .java 파일을 자동으로 해석하고 main() 메서드가 포함된 진입 클래스를 스스로 찾아 실행하며, 생성된 파일도 워크스페이스에 자동 반영합니다.","faq3_q":"Java 코드에서 로컬 SQLite 데이터베이스에 연결하거나 외부 .jar 파일을 추가할 수 있나요?","faq3_a":"네! 오프라인 jdbc:sqlite:... JDBC 드라이버가 기본 내장되어 있어 바로 SQL 쿼리를 수행할 수 있으며, 프로젝트의 libs/ 폴더에 호환 가능한 .jar 파일을 넣으면 클래스패스에 자동 등록됩니다.","faq4_q":"Scanner(System.in) 대화형 콘솔 입력이 정상적으로 작동하나요?","faq4_a":"네. Scanner나 BufferedReader가 입력을 대기할 때마다 프로그램이 안전하게 일시 정지하며 분할 화면 터미널에서 여러 줄의 입력값을 실시간으로 전달할 수 있습니다.","wb_eyebrow":"인터랙티브 JAVA 17 &amp; JDBC 워크벤치","sec_cap_title":"무거운 데스크톱 설정 없이 누리는 모던 Java 17의 모든 강력함","sec_cap_lead":"첫날 배우는 간결한 main() 메서드부터 다중 패키지 JDBC 데이터베이스 연동 프로젝트까지 안드로이드 기기 하나로 충분합니다.","f1_title":"모던 오프라인 Java 17 문법 &amp; 간결한 void main()","f1_desc":"record 클래스, sealed 인터페이스, switch -&gt; 화살표 표현식, instanceof 패턴 매칭, 텍스트 블록(\"\"\"\"), Stream API, java.time 및 학습자 친화적인 간결한 void main() 메서드를 100% 오프라인으로 지원합니다.","f1_badge":"Records · Sealed · Switch -&gt; · 텍스트 블록 · Streams","f2_title":"다중 패키지 OOP 컴파일 &amp; 0ms 바이트코드 캐시","f2_desc":"열린 탭과 프로젝트 폴더 전반의 다중 패키지 클래스를 한 번에 컴파일하고 main() 진입 클래스를 자동으로 판별하며, 해시 기반 바이트코드 캐시로 즉시(⚡ Cache) 재실행을 구현합니다.","f2_badge":"다중 클래스 패키지 · main() 자동 판별 · ⚡ 0ms 캐시","f3_title":"내장 오프라인 SQLite JDBC &amp; 커스텀 libs/*.jar 로드","f3_desc":"드라이버 설치 없이 DriverManager.getConnection(\"jdbc:sqlite:app.db\") 한 줄로 로컬 데이터베이스에 즉시 연결하거나, 프로젝트 내 libs/ 폴더에 외부 .jar 라이브러리를 넣어 클래스패스에 자동 추가할 수 있습니다.","f3_badge":"jdbc:sqlite 기본 내장 · 커스텀 .jar 자동 로드","f4_title":"실시간 Scanner(System.in) &amp; 깔끔한 예외 스택 트레이스","f4_desc":"[EOF] 제어가 포함된 대화형 Scanner 및 BufferedReader 입력 루프를 지원하며, System.exit() 호출 시 앱이 닫히지 않도록 안전하게 처리하고 내부 런타임 노이즈를 제거한 명확한 예외 위치만 출력합니다.","f4_badge":"실시간 System.in · 안전한 System.exit() · 정제된 진단","f5_title":"AST Java 자동완성, 코드 포매터 &amp; 8종 예제 템플릿","f5_desc":"Java/Kotlin 전용 21키 심볼 키보드, 오프라인 AST 멤버 자동완성, 원탭 Java 코드 정렬기 및 8가지 객체지향·자료구조 내장 템플릿으로 생산성을 높여줍니다.","f5_badge":"AST 자동완성 · Java 포매터 · 8종 Java 실전 예제","f6_title":"클라우드 Java 21+ &amp; 표준 SE 자동 라우팅","f6_desc":"Java 21+ 최신 문법이나 모바일 런타임 외 데스크톱 전용 표준 패키지를 테스트할 때는 다중 클래스 소스를 자동 번들링하여 클라우드 Java 환경에서 매끄럽게 실행합니다.","f6_badge":"Java 21+ 자동 폴백 · 다중 파일 클라우드 번들러","workflow_title":"SuperCode에서 다중 클래스 Java 프로젝트 빌드하는 방법","workflow_lead":"객체지향 프로그래밍 과제, 자료구조 구현, DB 연동 Java 애플리케이션 제작에 최적화된 과정입니다.","wf_foot_note":"유휴 인지형 15초 워치독 · 스레드 쿼터 보호 · 오프라인 SQLite JDBC 기본 내장","wf1_title":"Java 클래스 생성 및 선택적 .jar 라이브러리 추가","wf1_desc":"오프라인 AST 자동완성과 괄호·임포트 보조 기능을 활용해 패키지별 .java 클래스(및 libs/ 폴더 내 외부 .jar)를 구성합니다.","wf2_title":"Java 코드 블록 정렬 및 구문 검사","wf2_desc":"포맷 버튼으로 클래스, 메서드, Javadoc 주석 들여쓰기를 깔끔하게 맞추고 에러 레이더로 괄호나 문자열 누락을 점검합니다.","wf3_title":"온디바이스 오프라인 컴파일 및 바이트코드 캐싱","wf3_desc":"첫 실행 시 오프라인 Java SDK가 한 번 준비된 이후 기기 자체에서 Java 17 소스를 컴파일하며 바이트코드를 캐싱해 초고속 반복 실행을 제공합니다.","wf4_title":"System.in 실시간 입력 &amp; 로컬 DB/파일 연동","wf4_desc":"분할 터미널에서 콘솔 입력을 실시간으로 전달하고 JDBC로 로컬 SQLite DB를 조회하며 생성된 파일을 탐색기에서 바로 확인합니다."},"js_ide":{"metaTitle":"안드로이드 자바스크립트 실행 & 오프라인 ES2024 IDE — ESM 모듈 & Node 연동 | SuperCode","metaDesc":"HTML 래퍼 없이 안드로이드 자바스크립트 실행을 오프라인 격리 워커 콘솔에서 바로 시작하세요. ES2024 async/await, 다중 파일 ES 모듈 및 CommonJS, JSON 임포트, 무한 루프 즉시 차단, AST 자동완성과 클라우드 Node.js를 지원합니다.","hero_tag":"독립형 ES2024 JAVASCRIPT &amp; 다중 모듈 스튜디오","hero_h1":"멈춤 없는 격리 워커에서 <span class=\"text-gradient\">독립형 ES2024 JavaScript &amp; 모듈<\/span> 오프라인 실행.","hero_desc":"순수 자바스크립트 로직을 테스트하려고 번거로운 HTML 파일을 만들 필요가 없습니다. 안드로이드 자바스크립트 실행 전용 격리 워커 콘솔에서 <strong>ES2024 <code>async/await<\/code><\/strong>, <strong>다중 파일 ESM &amp; CommonJS 모듈<\/strong>, <strong>알고리즘 코드<\/strong>를 <strong>&lt;1ms 무한 루프 차단 보호<\/strong>와 함께 바로 구동하세요.","table_h2":"SuperCode JavaScript IDE vs 브라우저 콘솔 우회 방식","snippet_p":"<strong>SuperCode JavaScript IDE<\/strong>는 안드로이드 자바스크립트 실행을 위한 전용 오프라인 ES2024 러너이자 모듈형 코드 에디터입니다. UI와 분리된 격리 워커 스레드에서 다중 파일 ES 모듈과 CommonJS 스크립트를 구동하며 &lt;1ms 무한 루프 차단, 구조화된 콘솔 출력, AST 자동완성과 클라우드 Node.js 연동을 제공합니다.","table_caption":"안드로이드 JAVASCRIPT 실행 &amp; 에디터 비교 매트릭스","faq_lead":"HTML 없이 .js 파일 단독 실행하기, ES 모듈 분리, 무한 루프 보호 및 Node.js 연동에 대한 FAQ입니다.","cta_h2":"모던 ES2024 JavaScript를 언제 어디서나 코딩하고 실행하세요.","cta_desc":"Google Play에서 SuperCode IDE를 설치하고 오프라인 JS 다중 모듈, AST 자동완성, 풀스택 웹 DevTools를 함께 누리세요.","th_0":"JS 핵심 기능","th_1":"SuperCode JS IDE","th_2":"HTML 전용 웹 에디터","th_3":"온라인 JS 샌드박스","th_4":"CLI Node 직접 설치","tr1_c0":"독립형 JS 바로 실행","tr1_c1":"오프라인 .js / .mjs / .cjs 즉시 직접 실행","tr1_c2":"임시 HTML 파일 생성 강제","tr1_c3":"인터넷 연결 필수","tr1_c4":"100MB+ CLI 수동 설치","tr2_c0":"모듈 시스템 지원","tr2_c1":"로컬 ESM import/export + CommonJS + .json","tr2_c2":"file:// CORS 오류로 모듈 차단","tr2_c3":"단일 파일 또는 느린 CDN","tr2_c4":"지원됨","tr3_c0":"무한 루프 안전성","tr3_c1":"격리 워커 (&lt;1ms 즉시 종료, 버벅임 제로)","tr3_c2":"WebView 전체 화면 먹통","tr3_c3":"모바일 브라우저 탭 멈춤","tr3_c4":"수동 프로세스 종료","tr4_c0":"JS/TS 코드 정렬","tr4_c1":"100% 오프라인 JS/TS/JSX/JSON 포매터","tr4_c2":"기능 미흡 또는 플러그인 의존","tr4_c3":"온라인 상태에서만 가능","tr4_c4":"npm prettier 별도 설치","tr5_c0":"Node.js 서버 API","tr5_c1":"로컬 다중 모듈 자동 번들링 클라우드 Node 실행","tr5_c2":"브라우저 API만 사용 가능","tr5_c3":"브라우저 API만 사용 가능","tr5_c4":"로컬 CLI 환경 한정","faq1_q":"HTML 페이지를 만들지 않고 안드로이드에서 .js 파일만 단독으로 바로 실행할 수 있나요?","faq1_a":"네! 어떤 .js, .mjs, .cjs 파일에서든 실행 버튼만 누르면 SuperCode의 독립형 JavaScript 워커 콘솔이 즉시 가동되어 100% 오프라인으로 결과를 출력합니다.","faq2_q":"import/export나 require()로 여러 파일에 자바스크립트 코드를 나누어 작성할 수 있나요?","faq2_a":"네. ES 모듈(import / export)과 CommonJS(require / module.exports), 그리고 .json 데이터 임포트까지 로컬 프로젝트 폴더와 미저장 탭 전반에서 매끄럽게 동작합니다.","faq3_q":"실수로 while(true) 무한 루프를 실행하면 에디터가 멈추거나 작성 중인 코드가 날아가나요?","faq3_a":"절대 그렇지 않습니다. 스크립트가 UI와 분리된 격리 백그라운드 워커에서 15초 워치독 및 출력 폭주 차단기의 보호 아래 실행되므로 무한 루프도 1밀리초 이내에 안전하게 종료됩니다.","faq4_q":"HTML, CSS, WebAssembly가 포함된 시각적 DOM 웹사이트도 함께 만들고 싶다면 어떻게 하나요?","faq4_a":"SuperCode에는 두 환경이 모두 들어 있습니다! 순수 JS 모듈과 알고리즘 테스트에는 독립형 JavaScript IDE를, 실제 로컬 HTTP DOM 렌더링·반응형 뷰포트·웹 DevTools가 필요할 때는 풀스택 웹 &amp; PHP 스튜디오를 바로 사용하세요.","wb_eyebrow":"독립형 JAVASCRIPT 격리 워커 콘솔","sec_cap_title":"브라우저 탭에 종속되지 않는 진정한 독립형 JavaScript 런타임","sec_cap_lead":"자료구조, 비동기 파이프라인, JSON 데이터 가공, 모듈형 유틸리티를 즉각적인 피드백과 정확한 줄 번호 진단으로 테스트하세요.","f1_title":"ES6–ES2024 전체 문법 오프라인 완벽 지원","f1_desc":"async/await, Promise.allSettled/any, 제너레이터, 클래스 프라이빗 필드(#), 옵셔널 체이닝(?.), 널 병합(??), BigInt, structuredClone, 타이머 및 performance.now()를 오프라인으로 실행합니다.","f1_badge":"ES2024 · BigInt · 프라이빗 #필드 · structuredClone","f2_title":"다중 파일 ES 모듈 &amp; CommonJS 통합 링킹","f2_desc":"import/export 또는 require()/module.exports 문법으로 로컬 .js, .mjs, .cjs, .json 모듈을 자유롭게 불러오며, 미저장 열린 탭과 메인 진입 파일 자동 판별까지 지원합니다.","f2_badge":"import / export · require() · .json 모듈 임포트","f3_title":"UI 분리 백그라운드 워커 &amp; &lt;1ms 무한 루프 차단","f3_desc":"메인 UI 스레드가 아닌 전용 백그라운드 워커 스레드에서 구동됩니다. 실수로 작성한 while(true){} 무한 루프도 에디터 버벅임 전혀 없이 1밀리초 미만 만에 즉시 강제 종료합니다.","f3_badge":"UI 멈춤 제로 · 15초 워치독 · 1:1 줄 번호 에러 표시","f4_title":"구조화된 객체 콘솔 &amp; 실시간 대화형 표준 입력","f4_desc":"중첩된 객체, 배열, console.warn/error 레벨, 고정밀 타이머를 한눈에 읽기 쉽게 출력하며 CLI 스타일 자바스크립트 알고리즘 풀이를 위한 실시간 사용자 입력도 지원합니다.","f4_badge":"구조화 객체 출력 · 실시간 프롬프트 입력 · 분할 콘솔","f5_title":"JS/TS AST 자동완성 &amp; 원탭 Prettier 스타일 정렬","f5_desc":"전용 JS/TS 21키 심볼 프로필(=&gt;, ?., ===, ``, ${}), Array/Promise/JSON/Math/DOM 전반의 오프라인 AST 자동완성, 원자적 JS/TS/JSON 코드 포매터를 기본 탑재했습니다.","f5_badge":"JS/TS 심볼 바 · AST 자동완성 · JSON 구문 검증기","f6_title":"클라우드 Node.js 다중 파일 자동 번들러","f6_desc":"Node.js 코어 API(http, fs, crypto, child_process)나 // @cloud 지시어를 사용하면 로컬 다중 모듈을 하나의 Node.js 페이로드로 자동 번들링해 클라우드에서 실행합니다.","f6_badge":"Node.js API 자동 감지 · 다중 모듈 클라우드 번들","workflow_title":"SuperCode에서 모듈형 JavaScript 작성 및 테스트하기","workflow_lead":"JS 코딩 테스트 연습, 모듈 유틸리티 개발, API 페이로드 검증에 최적화된 흐름입니다.","wf_foot_note":"6종 내장 JavaScript 실전 예제 · .js · .mjs · .cjs · .ts · .json 완벽 지원","wf1_title":"독립형 .js, .mjs, .cjs 또는 .json 파일 생성","wf1_desc":"불필요한 index.html 래퍼 없이 순수 JavaScript 스크립트나 다중 모듈 패키지를 바로 작성합니다.","wf2_title":"깔끔한 비동기 &amp; 화살표 함수 고속 타이핑","wf2_desc":"=&gt;, ?., ===, 템플릿 리터럴 백틱(``) 원탭 키캡과 오프라인 AST 자동완성, 원탭 JS 포매터로 빠르게 코딩합니다.","wf3_title":"격리된 워커 콘솔에서 즉시 오프라인 실행","wf3_desc":"실행을 탭하여 로컬 모듈을 자동 링크하고 구조화된 콘솔 출력과 밀리초(ms) 단위 실행 시간을 확인합니다.","wf4_title":"라이브 DOM 프리뷰 전환 또는 Git 원격 푸시","wf4_desc":"브라우저 DOM·Canvas·WASM 렌더링이 필요할 때는 웹 스튜디오의 .html과 결합하거나 내장 비주얼 Git으로 바로 커밋합니다."},"lua_ide":{"metaTitle":"안드로이드 Lua 5.4 IDE & 오프라인 루아 스크립트 컴파일러 — 코루틴 & 모듈 | SuperCode","metaDesc":"안드로이드 오프라인에서 마이크로초 단위로 실행되는 네이티브 Lua 5.4.7 스크립팅 IDE. 메타테이블, 코루틴, 비트 연산, 다중 파일 require(), . 대 : 구분 AST 자동완성, 실시간 io.read()와 코드 정렬을 지원합니다.","hero_tag":"네이티브 오프라인 LUA 5.4.7 스크립팅 스튜디오","hero_h1":"게임 로직과 임베디드 스크립팅을 위한 초고속 <span class=\"text-gradient\">오프라인 Lua 5.4 IDE<\/span>.","hero_desc":"게임 상태 머신 프로토타이핑, 임베디드 로직, 자동화 규칙까지 <strong>네이티브 Lua 5.4.7<\/strong>로 <strong>마이크로초 단위<\/strong> 오프라인 실행을 경험하세요. <strong>다중 파일 <code>require()<\/code><\/strong>, <strong><code>.<\/code> 대 <code>:<\/code> 구분 AST 자동완성<\/strong>, 실시간 <strong><code>io.read()<\/code><\/strong>를 기본 제공합니다.","table_h2":"SuperCode Lua 5.4 스튜디오 vs 일반 모바일 텍스트 에디터","snippet_p":"<strong>SuperCode Lua IDE<\/strong>는 안드로이드 전용 네이티브 오프라인 Lua 5.4.7 스크립팅 스튜디오입니다. 마이크로초 실행 속도와 메모리 텔레메트리, 다중 파일 require() 모듈 해석, . 함수와 : 메서드를 구분하는 AST 자동완성, 원탭 Lua 코드 정렬 및 실시간 io.read() 콘솔 입력을 제공합니다.","table_caption":"안드로이드 LUA 5.4 스크립팅 IDE 기능 비교","faq_lead":"오프라인 Lua 5.4 문법 지원, 다중 파일 require() 모듈 분리 및 코드 정렬 관련 자주 묻는 질문입니다.","cta_h2":"안드로이드에서 네이티브 Lua 5.4 스크립트를 마이크로초 만에 실행하세요.","cta_desc":"Google Play에서 SuperCode IDE를 다운로드하고 오프라인 Lua 5.4.7, AST 자동완성, 다중 파일 워크스페이스를 만나보세요.","th_0":"Lua 핵심 역량","th_1":"SuperCode Lua 5.4 IDE","th_2":"일반 Lua 텍스트 편집기","th_3":"웹 기반 Lua 데모","tr1_c0":"런타임 엔진 버전","tr1_c1":"네이티브 오프라인 Lua 5.4.7 (~400 µs)","tr1_c2":"자체 실행 엔진 없음","tr1_c3":"인터넷 연결 필수","tr2_c0":"다중 모듈 해석","tr2_c1":"다중 파일 require() + 미저장 탭 연동","tr2_c2":"미지원","tr2_c3":"단일 스니펫만 실행","tr3_c0":"Lua 코드 인텔리전스","tr3_c1":". 함수 vs : 메서드 구분 AST + 오프라인 포매터","tr3_c2":"단순 키워드 색상 강조","tr3_c3":"일반 텍스트 입력창","tr4_c0":"대화형 입출력","tr4_c1":"실시간 io.read() + 워크스페이스 파일 동기화","tr4_c2":"미지원","tr4_c3":"정적 출력만 지원","tr5_c0":"상호운용 &amp; 확장","tr5_c1":"luajava.* 연동 + 클라우드 lpeg/socket/lfs","tr5_c2":"미지원","tr5_c3":"미지원","faq1_q":"SuperCode에서 오프라인으로 실행되는 Lua 버전은 무엇인가요?","faq1_a":"네이티브 Lua 5.4.7 엔진이 내장되어 있어 인터넷 없이 100% 오프라인으로 실행되며, 정수 나눗셈(//), 비트 연산자, &lt;const&gt; 및 &lt;close&gt; 변수 속성, 코루틴, 메타테이블, utf8 라이브러리를 모두 지원합니다.","faq2_q":"Lua 스크립트를 여러 파일로 나누고 require()로 불러올 수 있나요?","faq2_a":"네. require() 호출 시 프로젝트 폴더와 현재 열려 있는 에디터 탭을 자동으로 탐색해 모듈을 연결하며, io.open()으로 생성한 파일도 탐색기 트리에 즉시 동기화됩니다.","faq3_q":"오프라인 상태에서 Lua 코드 자동 정렬(포매팅)도 지원하나요?","faq3_a":"네. 포맷 버튼을 한 번 탭하면 function, if/then/else, for/do, repeat/until 블록과 중첩 테이블 생성자 들여쓰기를 오프라인에서 깔끔하게 정렬해 줍니다.","wb_eyebrow":"인터랙티브 LUA 5.4.7 워크벤치","sec_cap_title":"깃털처럼 가벼운 실행 속도와 본격 IDE 인텔리전스의 만남","sec_cap_lead":"주머니 속 스마트폰에서 수준 높은 Lua 코드 편집, 원탭 정렬, 다중 모듈 실행을 한 번에 처리하세요.","f1_title":"마이크로초 텔레메트리를 갖춘 네이티브 Lua 5.4.7","f1_desc":"// 정수 나눗셈, 비트 연산자(&amp; | ~ &lt;&lt; &gt;&gt;), &lt;const&gt; 및 &lt;close&gt; 속성 변수, 코루틴, 메타테이블, string.pack/unpack, utf8 모듈을 오프라인으로 실행하며 정확한 µs 소요 시간과 KB 메모리를 리포트합니다.","f1_badge":"Lua 5.4.7 · µs 정밀 계측 · KB 메모리 텔레메트리","f2_title":"다중 파일 require() &amp; 워크스페이스 파일 동기화","f2_desc":"게임 엔티티와 유틸리티 모듈을 하위 폴더로 깔끔하게 분리하세요. require('modules.vec2')가 저장된 파일과 미저장 탭을 넘나들며 자동 해석되고, io.open()으로 쓴 파일은 프로젝트 트리에 즉시 반영됩니다.","f2_badge":"다중 파일 require() · 진입점 자동 판별 · 파일 동기화","f3_title":"메서드 구분형(. vs :) AST 자동완성 &amp; 포매터","f3_desc":"테이블 일반 함수(string., table., math.)와 콜론 객체 메서드(str:, customObj:)를 문맥에 맞게 구분하여 추천하며, 전용 오프라인 Lua 코드 포매터와 `--` / `--[[ ]]` 주석 도구를 함께 제공합니다.","f3_badge":". 대 : 정밀 자동완성 · 오프라인 Lua 코드 포매터","f4_title":"대화형 io.read() 콘솔 &amp; 적응형 메모리 안전장치","f4_desc":"텍스트 어드벤처나 CLI 도구를 실시간 io.read() 프롬프트로 테스트할 수 있으며, 적응형 VM 메모리 상한과 CPU 타임아웃 가드가 기기 안정성을 지켜줍니다.","f4_badge":"실시간 io.read() · 8종 Lua 예제 · 클라우드 C 모듈 연동","workflow_title":"안드로이드에서 다중 모듈 Lua 스크립트 프로토타이핑하기","workflow_lead":"단일 스크립트 실험부터 모듈화된 게임 로직 설계까지 초고속 반복 개발을 지원합니다.","wf_foot_note":"네이티브 Lua 5.4.7 · Java luajava.* 상호운용 · 클라우드 Lua C 모듈 완벽 지원","wf1_title":"Lua 스크립트 생성 또는 내장 예제 불러오기","wf1_desc":"8가지 내장 Lua 스타터 예제를 선택하거나 탐색기에서 다중 파일 모듈 구조를 생성합니다.","wf2_title":"테이블 문맥 인식 자동완성 &amp; 원탭 정렬","wf2_desc":"표준 라이브러리와 커스텀 테이블 뒤에서 : 또는 .을 입력해 오프라인 추천을 받고 포맷 버튼으로 블록을 정렬합니다.","wf3_title":"마이크로초 단위의 초고속 오프라인 실행","wf3_desc":"실시간 io.read() 입력과 함께 즉시 코드를 구동하고 마이크로초(µs) 및 킬로바이트(KB) 실행 지표를 확인합니다.","wf4_title":"게임 엔진 또는 원격 서버로 즉시 배포","wf4_desc":"완성된 Lua 모듈을 비주얼 Git 저장소에 푸시하거나 SFTP를 통해 원격 서버에 원탭으로 동기화합니다."},"shell_ide":{"metaTitle":"안드로이드 쉘 스크립트(.sh / Bash) 실행 & 모바일 Kotlin IDE | SuperCode","metaDesc":"안드로이드에서 Linux Shell(.sh / Bash) 스크립트와 Kotlin(.kt) 코드를 작성, 정렬, 실행하세요. grep, awk, sed, sort 로컬 파이프라인 구동, 결과 파일 자동 동기화 및 원탭 Kotlin 컴파일을 지원합니다.","hero_tag":"네이티브 LINUX SHELL (.SH) &amp; KOTLIN 스튜디오","hero_h1":"안드로이드에서 <span class=\"text-gradient\">Linux Shell 파이프라인 &amp; Kotlin<\/span>으로 완성하는 자동화.","hero_desc":"프로젝트 폴더와 실시간 동기화되는 네이티브 <strong><code>grep<\/code>, <code>awk<\/code>, <code>sed<\/code>, <code>sort<\/code> &amp; <code>find<\/code><\/strong> 파이프라인으로 <strong><code>.sh<\/code> 쉘 스크립트<\/strong>를 로컬에서 작성·정렬·실행하고, <strong>Ubuntu Bash 5.2<\/strong> 및 <strong>Kotlin(<code>.kt<\/code>)<\/strong> 클라우드 컴파일까지 매끄럽게 활용하세요.","table_h2":"SuperCode Shell &amp; Kotlin 스튜디오 비교","snippet_p":"<strong>SuperCode Shell &amp; Kotlin 스튜디오<\/strong>는 안드로이드에서 grep, awk, sed, sort를 활용한 리눅스 쉘(.sh) 파이프라인 로컬 실행 및 프로젝트 폴더 자동 동기화는 물론, 오프라인 포매터와 매끄러운 GNU Bash 5.2·Kotlin(.kt) 클라우드 컴파일을 제공합니다.","table_caption":"안드로이드 쉘 스크립팅 &amp; KOTLIN 워크스페이스 비교","faq_lead":"안드로이드 공유 저장소에서의 .sh 실행 원리, awk/sed 파이프라인 및 Kotlin 컴파일 관련 FAQ입니다.","cta_h2":"스마트폰 하나로 어디서나 쉘 스크립트와 Kotlin을 구동하세요.","cta_desc":"Google Play에서 SuperCode IDE를 설치하고 네이티브 리눅스 쉘 파이프라인, Kotlin 실행, SFTP 서버 도구를 활용하세요.","th_0":"지원 역량","th_1":"SuperCode Shell + Kotlin","th_2":"기본 CLI 터미널 앱","th_3":"단순 스크립트 뷰어","tr1_c0":"공유 저장소 .sh 실행","tr1_c1":"안드로이드 noexec 제한 없이 깔끔하게 실행","tr1_c2":"/sdcard 경로에서 Permission denied 발생","tr1_c3":"실행 불가능","tr2_c0":"에디터 &amp; 코드 정렬","tr2_c1":"AST 힌트 + 오프라인 Shell &amp; Kotlin 포매터","tr2_c2":"작은 CLI nano/vi 편집기만 제공","tr2_c3":"구문 색상 표시만 지원","tr3_c0":"GNU Bash 5 &amp; Kotlin","tr3_c1":"클라우드 Ubuntu Bash 5.2 + Kotlin 러너 내장","tr3_c2":"수동 rootfs/JDK 무거운 설치 필요","tr3_c3":"미지원","tr4_c0":"원격 서버 배포","tr4_c1":"SFTP 3단계 원자적 저장 + 비주얼 Git 내장","tr4_c2":"수동 scp 명령어 입력","tr4_c3":"미지원","faq1_q":"안드로이드 공유 저장소는 chmod +x 권한을 막는데 SuperCode는 어떻게 일반 폴더의 .sh 스크립트를 실행하나요?","faq1_a":"SuperCode가 프로젝트 작업 경로($PWD)를 안드로이드 네이티브 쉘 실행 환경에 투명하게 매핑하여 구동한 뒤, 새로 생성되거나 변경된 출력 파일을 원래 프로젝트 폴더로 자동 동기화해 주기 때문입니다.","faq2_q":"SuperCode에서 Kotlin(.kt) 코드를 작성하고 실행할 수 있나요?","faq2_a":"네! Kotlin 및 Gradle(.kt, .kts, .gradle.kts) 구문 강조, 오프라인 AST 자동완성, 오프라인 코드 포매터는 물론 원탭 클라우드 Kotlin 컴파일 및 실행을 완벽히 지원합니다.","faq3_q":"안드로이드 기본 sh에 없는 GNU Bash 5 연관 배열 문법을 쓰면 어떻게 되나요?","faq3_a":"Bash 전용 고급 문법이나 # @cloud 지시어를 자동으로 감지하여 워크스페이스 스크립트를 Ubuntu GNU Bash 5.2 클라우드 환경으로 매끄럽게 라우팅해 실행합니다.","wb_eyebrow":"인터랙티브 SHELL 파이프라인 &amp; KOTLIN 워크벤치","sec_cap_title":"터치 친화적 스크립트 편집, 로컬 텍스트 파이프라인, 그리고 Kotlin","sec_cap_lead":"번거로운 외부 터미널 앱 전환 없이 정교한 스크립트 포매팅과 실제 파이프라인 실행을 한 화면에서 해결하세요.","f1_title":"네이티브 OS 쉘 실행 &amp; Toybox 텍스트 파이프라인","f1_desc":"일반적으로 chmod +x 실행 권한이 차단되는 안드로이드 공유 저장소에서도 grep, awk, sed, sort, uniq, wc, cut, tr, find, cat 및 파일 리다이렉션을 포함한 .sh 스크립트를 로컬에서 깔끔하게 구동합니다.","f1_badge":"grep · awk · sed · sort · uniq · find · 파이프","f2_title":"다중 스크립트 source 연동 &amp; 결과 파일 자동 동기화","f2_desc":"폴더 내 보조 .sh 스크립트를 source로 불러오고 실시간 대화형 read 입력을 받을 수 있으며, 스크립트가 생성한 리포트나 변환된 파일이 탐색기에 자동으로 나타납니다.","f2_badge":"다중 파일 source · 실시간 read 입력 · 파일 자동 동기화","f3_title":"GNU Bash 5.2 &amp; 원탭 Kotlin(.kt) 클라우드 스튜디오","f3_desc":"GNU Bash 5 전용 연관 배열 문법이 필요하거나 Kotlin 데이터 클래스, 코루틴, 함수형 코드를 컴파일하고 싶을 때 전용 클라우드 런타임으로 깔끔하게 자동 연결됩니다.","f3_badge":"Ubuntu Bash 5.2 · Kotlin .kt / .kts 원탭 실행","f4_title":"Shell &amp; Kotlin AST 자동완성 + 오프라인 코드 포매터","f4_desc":"${var:-default} 쉘 변수 확장 힌트, Kotlin AST 멤버 자동완성, Shell 및 Kotlin/Gradle 오프라인 포매터와 6가지 실전 Shell 템플릿을 기본 내장했습니다.","f4_badge":"Shell + Kotlin 포매터 · Dockerfile/Makefile 구문 강조","workflow_title":"쉘 자동화 스크립트 &amp; Kotlin 스니펫 실행 가이드","workflow_lead":"DevOps 서버 스크립트 점검, 로그 텍스트 가공, Kotlin 문법 실습을 위한 간결한 워크플로입니다.","wf_foot_note":"6종 내장 Shell 예제 · 120초 프로세스 트리 워치독 · SFTP 리눅스 권한 보존","wf1_title":"쉘 스크립트 또는 Kotlin 소스 파일 생성","wf1_desc":"전용 심볼 키보드와 정밀 구문 강조를 활용해 .sh, .bash, Makefile, Dockerfile 또는 .kt 파일을 작성합니다.","wf2_title":"반복문, 분기문 &amp; Kotlin 블록 원탭 자동 정렬","wf2_desc":"쉘 스크립트의 if/fi, case/esac 구조와 Kotlin 클래스를 오프라인에서 탭 한 번으로 가지런히 정렬합니다.","wf3_title":"기기 로컬 쉘 또는 클라우드 Bash / Kotlin 실행","wf3_desc":"POSIX 쉘 파이프라인은 기기 로컬에서 즉시 실행하고, GNU Bash 5.2 및 Kotlin 코드는 클라우드로 매끄럽게 컴파일합니다.","wf4_title":"검증된 스크립트를 실서버로 즉시 배포","wf4_desc":"작동이 확인된 쉘 스크립트를 POSIX 실행 권한을 보존한 채 SFTP로 업로드하거나 비주얼 Git으로 커밋합니다."},"web_ide":{"metaTitle":"모바일 PHP 로컬 서버 웹 에디터 — 안드로이드 HTML5, CSS3, JS, WASM, SQL & SFTP | SuperCode","metaDesc":"안드로이드 오프라인에서 풀스택 웹사이트를 제작하세요. HTML5, CSS3, ES 모듈, WebAssembly(.wasm), 동적 PHP + PDO SQLite DB를 구동하는 모바일 PHP 로컬 서버 웹 에디터와 반응형 DevTools REPL, SFTP 배포를 지원합니다.","hero_tag":"풀스택 WEB · PHP · WASM · SQL · SFTP 스튜디오","hero_h1":"내장 DevTools를 갖춘 풀스택 <span class=\"text-gradient\">웹, 오프라인 PHP &amp; WASM<\/span> 스튜디오.","hero_desc":"반쪽짜리 정적 <code>file://<\/code> 뷰어가 아닌, 주머니 속 완벽한 모바일 PHP 로컬 서버 웹 에디터입니다. <strong>HTML5, CSS3, ES 모듈 &amp; WebAssembly(<code>.wasm<\/code>)<\/strong>부터 <strong>오프라인 동적 PHP<\/strong>, <strong>PDO SQLite 데이터베이스<\/strong>, <strong>반응형 DevTools<\/strong>, 실시간 <strong>FTP/SFTP 원격 배포<\/strong>까지 하나로 통합했습니다.","table_h2":"SuperCode 웹 &amp; PHP 스튜디오 vs 일반 모바일 HTML 뷰어","snippet_p":"<strong>SuperCode 웹 &amp; PHP 스튜디오<\/strong>는 안드로이드를 위한 풀스택 모바일 PHP 로컬 서버 웹 에디터입니다. 실제 로컬 HTTP 서버를 내장해 HTML5, CSS3, ES 모듈, WebAssembly(.wasm), PDO SQLite가 결합된 오프라인 동적 PHP, 3모드 반응형 뷰포트 전환기, JS REPL 탑재 웹 DevTools 및 실시간 SFTP 배포를 지원합니다.","table_caption":"안드로이드 풀스택 웹 &amp; PHP 개발 환경 비교 매트릭스","faq_lead":"오프라인 PHP + SQLite 구동, ES 모듈 / fetch() / WASM 지원, 웹 DevTools 및 SFTP 배포에 대한 답변입니다.","cta_h2":"HTML, WASM, PHP, SQL 풀스택 로컬 서버를 주머니 속에 휴대하세요.","cta_desc":"Google Play에서 SuperCode IDE를 다운로드하고 안드로이드에서 완성도 높은 웹앱을 제작·디버깅·배포하세요.","th_0":"웹 개발 역량","th_1":"SuperCode 웹 + PHP 스튜디오","th_2":"기본 모바일 HTML 편집기","th_3":"클라우드 웹 개발 환경","tr1_c0":"서버 오리진 &amp; WASM","tr1_c1":"실제 로컬 HTTP + ES 모듈 + .wasm 스트리밍","tr1_c2":"file:// CORS 제한으로 fetch·모듈 차단","tr1_c3":"상시 인터넷 연결 필수","tr2_c0":"백엔드 PHP &amp; SQL","tr2_c1":"100% 오프라인 PHP + $_SESSION + PDO SQLite","tr2_c2":"정적 프론트엔드 HTML/JS만 가능","tr2_c3":"유료 클라우드 컨테이너 필요","tr3_c0":"반응형 &amp; DevTools","tr3_c1":"모바일/태블릿/데스크톱 + Net 로그 + 실시간 JS REPL","tr3_c2":"단순 alert() 또는 텍스트 로그만 표시","tr3_c3":"폰 화면에 비좁은 데스크톱 UI","tr4_c0":"미디어 &amp; 캡처 출력","tr4_c1":"카메라/파일 업로드 + Canvas/Blob + 2560px PNG","tr4_c2":"&lt;input type=file&gt; 및 blob: 작동 오류","tr4_c3":"원격 파일 다운로드 번거로움","tr5_c0":"원격 호스팅 연동","tr5_c1":"실시간 SFTP/FTPS 프리뷰 + 3단계 원자적 저장","tr5_c2":"외부 FTP 앱으로 수동 재업로드","tr5_c3":"클라우드 종속 환경","faq1_q":"인터넷 없이 안드로이드에서 동적 PHP 웹사이트와 SQL 데이터베이스를 실행할 수 있나요?","faq1_a":"네! .php 페이지, REST JSON 엔드포인트, 세션 유지, 파일 업로드 폼, 다중 파일 include가 모두 100% 오프라인으로 구동되며 PDO('sqlite:...') 및 SQLite3 데이터베이스 연동이 기본 내장되어 있습니다.","faq2_q":"ES6 모듈(&lt;script type=\"module\"&gt;), fetch(), WebAssembly(.wasm)도 정상 작동하나요?","faq2_a":"네. SuperCode가 application/wasm을 포함한 65종 이상의 MIME 타입을 지원하는 실제 로컬 HTTP 서버 위에서 프로젝트를 구동하므로 fetch(), ES 모듈, WebGL 3D 모델, WebAssembly.instantiateStreaming()이 별도 설정 없이 즉시 작동합니다.","faq3_q":"스마트폰 화면에서 자바스크립트 에러나 데스크톱 레이아웃은 어떻게 디버깅하나요?","faq3_a":"프리뷰 화면의 드래그형 다이내믹 아일랜드 알약 버튼을 눌러 모바일·태블릿(768dp)·데스크톱 뷰포트를 즉시 전환하거나, 크기 조절형 웹 DevTools 서랍을 열어 Error/Warn/Net 로그 필터링과 실시간 JS REPL 명령 실행을 수행할 수 있습니다.","faq4_q":"원격 FTP 또는 SFTP 서버에 호스팅된 실제 웹사이트도 미리 보고 수정할 수 있나요?","faq4_a":"네. SFTP/FTPS/FTP 워크스페이스에 서버를 마운트하면 원격 HTML/CSS/JS/PHP 탭을 3단계 원자적 저장으로 안전하게 직접 편집할 수 있으며, 실행을 누르면 연관 에셋을 자동 캐싱해 원격 페이지를 실시간으로 미리 보여줍니다.","wb_eyebrow":"풀스택 HTTP, 오프라인 PHP, WASM &amp; DEVTOOLS 워크벤치","sec_cap_title":"안드로이드 위에 하나로 연결된 모던 웹 엔지니어링 6계층","sec_cap_lead":"프론트엔드 ES 모듈, 바이너리 WebAssembly, 백엔드 PHP 세션, 관계형 SQL 데이터베이스, DevTools 디버깅과 SFTP 원격 배포가 유기적으로 작동합니다.","f1_title":"HTML5, CSS3, JS &amp; WASM을 위한 실제 로컬 HTTP 오리진","f1_desc":"CORS 오류가 발생하는 file:// 경로 대신 진짜 로컬 HTTP/1.1 서버로 프로젝트를 서빙하여 fetch(), &lt;script type=\"module\"&gt;, WebAssembly.instantiateStreaming()(.wasm), WebGL .glb/.gltf 에셋, IndexedDB, HTTP 206 미디어 탐색을 완벽히 지원합니다.","f1_badge":"65+ MIME 타입 · ES 모듈 · application/wasm · HTTP 206","f2_title":"100% 오프라인 동적 PHP 백엔드 엔진","f2_desc":"$_GET, $_POST, 영구 $_SESSION, $_FILES 파일 업로드, JSON REST 응답 헤더, password_hash()는 물론 다중 페이지 .php 템플릿, OOP 클래스, 클로저, match, include/require를 완전 오프라인으로 실행합니다.","f2_badge":"$_GET / $_POST / $_SESSION · JSON API · 오프라인 PHP","f3_title":"PDO &amp; SQLite3 기반 오프라인 SQL 데이터베이스 통합","f3_desc":"new PDO('sqlite:app.db') 또는 SQLite3의 프리페어드 스테이트먼트(? 및 :named 바인딩)와 ACID 트랜잭션으로 데이터 기반 PHP 웹앱을 구축하고, 내장 SQL IDE에서 테이블을 즉시 조회할 수 있습니다.","f3_badge":"PDO('sqlite:...') · Prepared Statements · ACID 트랜잭션","f4_title":"플로팅 DevTools 콘솔, 네트워크 로그 &amp; 실시간 JS REPL","f4_desc":"실시간 HTTP 요청(GET /api.php -&gt; 200 · 3ms · 1.2 KB)을 추적하고 All / Error / Warn / Net 필터링, 구조화된 DOM/객체 트리 탐색 및 &gt; Run JavaScript... 대화형 REPL 평가를 수행합니다.","f4_badge":"네트워크 타이밍 · 에러 배지 · 대화형 JS REPL","f5_title":"3모드 반응형 뷰포트 전환기 &amp; 2560px 고해상도 캡처","f5_desc":"드래그 가능한 다이내믹 아일랜드에서 모바일, 태블릿(768dp), 데스크톱 레이아웃을 즉시 전환하고 카메라/갤러리 &lt;input type=\"file\"&gt; 업로드를 테스트한 뒤 선명한 2560px PNG 스크린샷으로 내보냅니다.","f5_badge":"모바일 / 태블릿 / 데스크톱 · 2560px PNG 내보내기","f6_title":"원격 FTP / FTPS / SFTP 실시간 웹 프리뷰 &amp; 배포","f6_desc":"SFTP나 FTPS로 연결된 실서버 사이트를 수정 중인가요? 실행을 누르면 상대 경로의 CSS, JS, 이미지를 온디맨드로 캐싱해 원격 페이지를 즉시 미리 보여주고 3단계 원자적 저장으로 호스팅 서버에 안전하게 반영합니다.","f6_badge":"실시간 원격 프리뷰 · 원자적 SFTP / FTPS 퍼블리싱","workflow_title":"안드로이드에서 풀스택 웹사이트 제작, 디버깅 &amp; 배포하기","workflow_lead":"로컬 HTML/CSS/WASM 및 PHP+SQL 프로토타이핑부터 실서버 배포까지 끊김 없이 진행하세요.","wf_foot_note":"좌측 엣지 스와이프로 탐색기 즉시 복귀 · 원탭 브라우저 캐시 및 PHP 세션 초기화","wf1_title":"HTML5, CSS3, JS, WASM &amp; PHP 파일 작성","wf1_desc":"AST HTML/CSS/JS/PHP 자동완성과 문서 내부의 &lt;script&gt;·&lt;style&gt; 블록까지 한 번에 들여쓰기하는 재귀 포매터로 다중 파일 웹 프로젝트를 편집합니다.","wf2_title":"오프라인 PHP 폼 &amp; REST API를 SQL DB에 연결","wf2_desc":"PDO 프리페어드 스테이트먼트로 로컬 .db SQLite 데이터베이스를 질의하거나 SuperCode의 SQL 스튜디오에서 초기 테이블 데이터를 구성합니다.","wf3_title":"모바일·태블릿·데스크톱 반응형 프리뷰 &amp; DevTools 점검","wf3_desc":"뷰포트 크기를 즉시 전환하며 크기 조절형 DevTools 서랍에서 네트워크 상태와 JS 에러를 점검하고 JS REPL에서 실시간 DOM 수정을 테스트합니다.","wf4_title":"웹 호스팅 서버 또는 GitHub Pages로 즉시 퍼블리싱","wf4_desc":"정적/WASM 빌드를 비주얼 Git으로 GitHub Pages에 푸시하거나 PHP 및 웹 에셋을 SFTP/FTPS를 통해 운영 VPS에 안전하게 배포합니다."},"sql_ide":{"metaTitle":"안드로이드 오프라인 SQL 연습 및 .db 뷰어 — SQLite 탐색기, CSV 임포트 & MySQL | SuperCode","metaDesc":"안드로이드에서 오프라인 SQL 연습 및 .db 뷰어를 하나로 해결하세요. 윈도우 함수, 재귀 CTE, JSON 쿼리, 9가지 출력 포맷(Box, Markdown, CSV, JSON), CSV/JSON 임포트와 클라우드 MySQL 8.0을 지원합니다.","hero_tag":"전용 오프라인 SQL IDE &amp; .DB 데이터베이스 탐색기","hero_h1":"안드로이드 오프라인에서 <span class=\"text-gradient\">모던 SQL 실행 &amp; .db 데이터베이스 탐색<\/span>.","hero_desc":"데이터베이스 엔지니어, 데이터 분석가, SQL 수험생을 위해 설계된 오프라인 SQL 연습 및 .db 뷰어 워크스페이스입니다. <strong>윈도우 함수, 재귀 CTE, JSONB &amp; 전문 검색<\/strong>을 <strong>9가지 정밀 포맷<\/strong>으로 오프라인 실행하고, 바이너리 <strong><code>.db/.sqlite<\/code> 파일<\/strong>을 원탭으로 분석하며 <strong>CSV/JSON 데이터셋<\/strong>을 즉시 불러오세요.","table_h2":"SuperCode SQL IDE vs 일반 모바일 DB 뷰어 앱","snippet_p":"<strong>SuperCode SQL IDE<\/strong>는 안드로이드를 위한 전용 오프라인 SQL 연습 및 .db 뷰어 스튜디오입니다. 윈도우 함수, 재귀 CTE, JSONB 경로, 전문 검색, 60종 이상의 통계·정규식 함수, 9가지 출력 모드(Box, Markdown, CSV, JSON), 원탭 .db/.sqlite 분석, CSV/JSON 임포트와 클라우드 MySQL 8.0을 통합했습니다.","table_caption":"안드로이드 SQL IDE &amp; 데이터베이스 뷰어 비교","faq_lead":"오프라인 SQL 코딩 테스트 연습, 휴대폰 .db/.sqlite 파일 열기, CSV/JSON 임포트 및 MySQL 문법에 대한 FAQ입니다.","cta_h2":"안드로이드 오프라인에서 SQL을 마스터하고 DB를 자유롭게 관리하세요.","cta_desc":"Google Play에서 SuperCode IDE를 설치하고 오프라인 SQL 러너, 원탭 .db 탐색기, CSV/JSON 데이터 스튜디오를 바로 활용하세요.","th_0":"SQL 핵심 기능","th_1":"SuperCode SQL 스튜디오","th_2":"단순 .db 테이블 뷰어","th_3":"온라인 SQL 실습 사이트","tr1_c0":"오프라인 SQL 엔진","tr1_c1":"윈도우 함수 + 재귀 CTE + JSONB + FTS 오프라인","tr1_c2":"기초 SELECT / 단순 표 열람만 가능","tr1_c3":"상시 인터넷 연결 필수","tr2_c0":"출력 &amp; 내보내기 포맷","tr2_c1":"9가지 모드 (Box, Markdown, CSV, JSON, INSERT...)","tr2_c2":"고정된 GUI 격자 화면만 제공","tr2_c3":"웹 HTML 테이블만 출력","tr3_c0":"데이터 임포트 &amp; 동기화","tr3_c1":"CSV, TSV &amp; JSON 배열 임포트 + 폴더 자동 동기화","tr3_c2":"유료 결제 필요 또는 미지원","tr3_c3":"수동 INSERT 구문 붙여넣기","tr4_c0":"MySQL 문법 호환성","tr4_c1":"로컬 DDL 자동 호환 + 클라우드 MySQL 8.0 프로시저","tr4_c2":"엄격한 기본 SQLite 문법만 허용","tr4_c3":"새로고침 시 초기화되는 세션","tr5_c0":"풀스택 백엔드 연동","tr5_c1":"로컬 PHP PDO 및 Java JDBC와 .db 파일 즉시 공유","tr5_c2":"고립된 단독 뷰어 앱","tr5_c3":"고립된 브라우저 탭","faq1_q":"별도 데이터베이스 서버 구축 없이 오프라인으로 SQL 쿼리 연습을 할 수 있나요?","faq1_a":"네! 아무 .sql 파일이나 만들고 실행 버튼만 누르면 CREATE, INSERT, JOIN, 재귀 CTE, 윈도우 함수가 포함된 다중 쿼리가 100% 오프라인으로 실행되며 깔끔한 유니코드 박스 표로 출력됩니다.","faq2_q":"스마트폰에 저장된 기존 .db 또는 .sqlite 파일도 열어서 조회할 수 있나요?","faq2_a":"네. .db, .sqlite, .sqlite3, .db3 파일을 탭하거나 실행하면 모든 테이블, 뷰, 인덱스, 스키마 구조를 즉시 보여주며, 같은 프로젝트 폴더 안의 .sql 스크립트에서 해당 DB를 바로 질의하고 수정할 수 있습니다.","faq3_q":"AUTO_INCREMENT, SHOW TABLES, DESCRIBE나 저장 프로시저 같은 MySQL 문법도 지원하나요?","faq3_a":"자주 쓰는 MySQL/PostgreSQL DDL 및 조회 명령어(AUTO_INCREMENT, ENUM, SHOW TABLES, DESCRIBE, ILIKE)는 기기 로컬에서 오프라인으로 즉시 호환 실행되며, 서버 전용 MySQL 8.0 저장 프로시저와 트리거는 클라우드 MySQL 8.0으로 자동 연결됩니다.","faq4_q":"SQL 쿼리 실행 결과를 CSV, Markdown 또는 JSON 파일로 어떻게 내보내나요?","faq4_a":"SELECT 쿼리 앞에 `.mode csv`(또는 `.mode markdown` / `.mode json`)와 `.once output.csv`를 추가해 실행하면 결과 파일이 현재 프로젝트 폴더에 즉시 생성됩니다.","wb_eyebrow":"인터랙티브 오프라인 SQL &amp; 데이터베이스 워크벤치","sec_cap_title":"데스크톱급 SQL 데이터 분석, 바이너리 DB 검사 &amp; 폭넓은 방언 호환성","sec_cap_lead":"한글·영문 글자 폭까지 반듯하게 정렬되는 표 출력으로 인메모리 샌드박스와 영구 다중 테이블 DB 파일을 자유자재로 다루세요.","f1_title":"모던 오프라인 SQL: 윈도우 함수, 재귀 CTE &amp; JSONB","f1_desc":"ROW_NUMBER/RANK/DENSE_RANK/LAG/LEAD OVER(...), WITH RECURSIVE 재귀 쿼리, RETURNING, UPSERT, -&gt; 및 -&gt;&gt; JSON 경로 추출, json_each(), BM25 전문 검색을 100% 오프라인으로 지원합니다.","f1_badge":"윈도우 함수 · 재귀 CTE · JSONB &amp; 전문 검색","f2_title":"9가지 결과 렌더링 모드 &amp; 파일 내보내기 파이프라인","f2_desc":"한글 글자 폭까지 깔끔하게 맞춰지는 유니코드 박스 그리드(┌──┬──┐)를 기본 제공하며, .mode 명령으로 table, markdown, csv, tsv, json, line, list, SQL insert 모드로 전환하거나 .once로 파일로 바로 추출합니다.","f2_badge":"box · markdown · csv · json · table · insert","f3_title":"원탭 .db / .sqlite 바이너리 탐색기 &amp; 자동 마운트","f3_desc":".db, .sqlite, .sqlite3, .db3 파일을 탭하면 페이지 메타데이터, 테이블, 뷰, 인덱스, 전체 CREATE 스키마를 즉시 분석합니다. 같은 폴더의 .sql 쿼리는 기존 DB 파일을 자동으로 마운트해 질의합니다!","f3_badge":".db / .sqlite3 즉시 열기 · ATTACH DATABASE 지원","f4_title":"CSV / TSV / JSON 자동 임포트 &amp; 60+ 통계·암호화 함수","f4_desc":".import --csv / --json 명령 한 줄로 CSV, TSV, JSON 객체 배열을 타입이 추론된 테이블로 즉시 적재하고, SHA256, REGEXP_EXTRACT, MEDIAN, STDDEV, PERCENTILE, UUID 등 60종 이상의 내장 함수를 활용하세요.","f4_badge":".import CSV/JSON · SHA256 · REGEXP · MEDIAN/STDDEV","f5_title":"MySQL / PostgreSQL 문법 호환 &amp; 대화형 READ_STDIN()","f5_desc":"일상적인 AUTO_INCREMENT, SERIAL, ENUM, SHOW TABLES, DESCRIBE, ILIKE 쿼리를 번거로운 문법 수정 없이 로컬에서 바로 실행하며, SQL 내부에서 READ_STDIN()으로 실시간 콘솔 파라미터를 입력받을 수 있습니다.","f5_badge":"SHOW TABLES / DESCRIBE · 대화형 READ_STDIN()","f6_title":"다중 파일 SQL 파이프라인 &amp; 클라우드 MySQL 8.0","f6_desc":"01_schema.sql -&gt; 02_seed.sql -&gt; 03_report.sql 순서로 다중 스크립트를 자동 연쇄 실행하거나, DELIMITER·CREATE PROCEDURE·CALL·JSON_TABLE 등 MySQL 8.0 저장 프로시저를 클라우드 MySQL 클러스터에서 구동합니다.","f6_badge":"다중 파일 순차 실행 · 클라우드 MySQL 8.0","workflow_title":"SuperCode에서 데이터베이스 조회 및 데이터셋 임포트하기","workflow_lead":"안드로이드 워크스페이스에 그대로 보존되는 깔끔한 스크립트 중심 DB 작업 흐름입니다.","wf_foot_note":"6종 내장 SQL 실전 예제 · 로컬 PHP PDO 및 Java 17 JDBC와 직접 DB 파일 공유","wf1_title":".db 데이터베이스 열기 또는 .sql 스크립트 생성","wf1_desc":"로컬 .db/.sqlite 파일을 탭해 스키마를 한눈에 확인하거나 오프라인 AST SQL 자동완성·포매터로 .sql 스크립트를 작성합니다.","wf2_title":"초기 테이블 시딩 또는 CSV &amp; JSON 파일 적재","wf2_desc":"프로젝트 폴더에 있는 CSV, TSV, JSON 데이터셋을 단일 명령어로 관계형 테이블에 즉시 불러옵니다.","wf3_title":"오프라인 다중 구문 SQL 쿼리 실행","wf3_desc":"분할 화면 콘솔에서 유니코드 박스 표, 마크다운 테이블, JSON 출력을 확인하고 필요 시 READ_STDIN() 파라미터를 입력합니다.","wf4_title":"깔끔한 리포트 내보내기 &amp; PHP/Java 연동","wf4_desc":"업데이트된 .db 파일이나 .csv/.json 리포트를 프로젝트 폴더에 저장하면 SuperCode의 PHP PDO 및 Java JDBC에서 즉시 함께 사용할 수 있습니다!"},"git_client":{"metaTitle":"안드로이드 비주얼 Git 클라이언트 — 클론, 타임머신 Diff & 병합 충돌 해결 UI | SuperCode","metaDesc":"SuperCode IDE에 기본 내장된 완벽한 안드로이드 비주얼 Git 클라이언트. PAT 토큰으로 GitHub/GitLab/Gitee 저장소를 클론하고 컬러 커밋 Diff 비교, 브랜치 전환, 자동 Stash Pull 및 시각적 병합 충돌 해결을 수행하세요.","hero_tag":"자체 내장형 비주얼 GIT V2.0 워크스테이션","hero_h1":"안드로이드에서 완성하는 <span class=\"text-gradient\">비주얼 Git, 타임머신 Diff &amp; 충돌 병합<\/span>.","hero_desc":"복잡한 외부 터미널 패키지 설치가 필요 없는 안드로이드 비주얼 Git 클라이언트입니다. HTTPS 토큰으로 <strong>GitHub, GitLab, Gitee &amp; Bitbucket<\/strong> 저장소를 클론하고, <strong>컬러 통합 Diff<\/strong> 점검, <strong>자동 Stash &amp; 탭 핫 리로드 Pull<\/strong>, 그리고 <strong>원탭 시각적 병합 충돌 해결<\/strong>까지 터치로 깔끔하게 제어하세요.","table_h2":"SuperCode 비주얼 Git vs 타 안드로이드 Git 워크플로 비교","snippet_p":"<strong>SuperCode 안드로이드 비주얼 Git 클라이언트<\/strong>는 앱 내부에 자체 통합된 네이티브 Git 워크스테이션입니다. HTTPS + PAT 클론, 다중 저장소 전환, 브랜치 관리, 자동 Stash 스마트 Pull, 컬러 통합 Diff가 탑재된 120개 커밋 타임머신, 비주얼 병합 충돌 해결기를 외부 터미널 없이 제공합니다.","table_caption":"안드로이드 GIT 버전 관리 워크플로 매트릭스","faq_lead":"GitHub 개인 액세스 토큰(PAT) 인증, 비공개 저장소 연동, 병합 충돌 해결 및 오프라인 커밋에 관한 실전 FAQ입니다.","cta_h2":"안드로이드에서 저장소, Diff 비교, 병합까지 손끝으로 완벽히 제어하세요.","cta_desc":"Google Play에서 SuperCode IDE를 다운로드하고 10종 이상의 오프라인 코딩 환경과 결합된 비주얼 Git 클라이언트를 경험하세요.","th_0":"Git 워크플로 항목","th_1":"SuperCode 비주얼 Git V2","th_2":"기본 모바일 Git 플러그인","th_3":"CLI 터미널 Git","tr1_c0":"초기 설정 &amp; 의존성","tr1_c1":"무설정 내장 엔진 + index.lock 자동 복구","tr1_c2":"잦은 플러그인 오류 및 인증 실패","tr1_c3":"수동 패키지 설치 + SSH/PAT 설정","tr2_c0":"로컬 수정 중 Pull","tr2_c1":"자동 Stash + 복원 + 커서 보존 탭 리로드","tr2_c2":"체크아웃 충돌 에러로 중단","tr2_c3":"수동 git stash / pop 명령어 입력","tr3_c0":"히스토리 &amp; 코드 Diff","tr3_c1":"120개 커밋 타임머신 + 2D 컬러 통합 Diff","tr3_c2":"단순 텍스트 로그 목록만 표시","tr3_c3":"좁은 폰 화면에서 스크롤 불편","tr4_c0":"병합 충돌 해결","tr4_c1":"비주얼 카드: 현재 / 수신 / 둘 다 유지 원탭 선택","tr4_c2":"원시 &lt;&lt;&lt;&lt;&lt;&lt;&lt; 마커 직접 수동 편집","tr4_c3":"vim에서 수동 마커 삭제","tr5_c0":"Detached HEAD 안전망","tr5_c1":"원탭 복구 배너 (+ 새 브랜치 생성 / 복귀)","tr5_c2":"작업한 커밋 유실 위험 높음","tr5_c3":"복잡한 CLI 상태 메시지","faq1_q":"GitHub, GitLab, Gitee의 비공개(Private) 저장소는 어떻게 인증하나요?","faq1_a":"GitHub/GitLab/Gitee에서 repo 권한이 부여된 HTTPS 개인 액세스 토큰(PAT)을 발급받아 클론, 커밋 &amp; 푸시 또는 Pull 시 토큰 입력란에 붙여넣으세요. 암호화되어 안전하게 저장되므로 매번 다시 입력할 필요가 없습니다.","faq2_q":"저장하지 않은 탭이나 아직 커밋하지 않은 수정 사항이 있는 상태에서 Pull을 누르면 어떻게 되나요?","faq2_a":"SuperCode가 먼저 미저장 탭을 디스크에 기록한 뒤 추적 중인 미커밋 변경분을 자동으로 Stash하고, 최신 원격 커밋을 받아 로컬 작업을 다시 적용한 다음 열린 탭을 정확한 커서 줄 위치 그대로 새로고침합니다.","faq3_q":"이전 커밋에서 어떤 코드가 바뀌었는지 확인하거나 과거 시점으로 되돌리려면 어떻게 하나요?","faq3_a":"Git 대시보드에서 Git 타임머신을 열고 타임라인의 원하는 커밋을 탭하세요. 코드 변경 보기(Commit Diff)로 컬러 통합 Diff를 열람하거나, 체크아웃(읽기 전용)으로 스냅샷을 안전하게 살펴보고, 하드 리셋으로 브랜치를 되감을 수 있습니다.","faq4_q":"인터넷 연결이 없는 오프라인 상태에서도 커밋할 수 있나요?","faq4_a":"네! 스테이징, 로컬 커밋 기록, 새 브랜치 생성, 커밋 히스토리 및 통합 Diff 열람, 병합 충돌 해결까지 모두 오프라인에서 작동하며, 나중에 네트워크에 연결되었을 때 원격 origin으로 한 번에 푸시할 수 있습니다.","wb_eyebrow":"인터랙티브 GIT 대시보드, DIFF &amp; 병합 워크벤치","sec_cap_title":"모바일 터치 환경을 위해 처음부터 다시 설계한 핵심 Git 워크플로","sec_cap_lead":"저장소 잠금 자동 복구, 미저장 탭 자동 플러시, Detached HEAD 구조 배너까지 갖춰 모바일 버전 관리의 실수를 원천 차단합니다.","f1_title":"택티컬 Git 대시보드 &amp; 다중 저장소 원탭 전환기","f1_desc":"마운트된 저장소, 활성 브랜치, 짧은 커밋 해시, 실시간 원격 ↑ Ahead / ↓ Behind 카운터, 수정/추가/삭제/충돌 파일 수를 한눈에 파악하고 여러 저장소를 원탭으로 전환합니다.","f1_badge":"다중 저장소 전환 · ↑Ahead ↓Behind · 기존 폴더 마운트","f2_title":"HTTPS + PAT 클론 &amp; 암호화 자격증명 영구 보관","f2_desc":"개인 액세스 토큰(PAT)을 사용해 GitHub, GitLab, Gitee, Bitbucket 및 자체 호스팅 Git 서버의 공개·비공개 저장소를 클론하세요. 대상 폴더명이 자동으로 채워지며 토큰은 이후 푸시를 위해 안전하게 암호화 저장됩니다.","f2_badge":"GitHub / GitLab / Gitee PAT · 실시간 전송 진행률","f3_title":"미저장 탭 자동 플러시, 변경 내역 미리보기 &amp; 작성자 설정","f3_desc":"커밋 실행 전 수정 중인 열린 에디터 탭을 디스크에 자동으로 먼저 저장하여 누락을 방지하며, 최대 80개 변경 파일을 [M]/[A]/[U]/[D] 배지로 미리 보여주고 커밋 작성자 이름·이메일 설정을 지원합니다.","f3_badge":"편집 누락 제로 · 커스텀 작성자 · 업스트림 자동 바인딩","f4_title":"자동 Stash &amp; 커서 위치 보존 핫 리로드를 갖춘 스마트 Pull","f4_desc":"로컬에 아직 커밋하지 않은 수정본이 있을 때 Pull을 눌러도 걱정 없습니다. 불필요한 임시 커밋 없이 안전하게 자동 Stash 후 원격 변경분을 받고 로컬 작업을 복원한 뒤, 열린 탭을 원래 커서 줄·열 그대로 새로고침합니다!","f4_badge":"무소음 자동 Stash · 커서 유지 인플레이스 탭 리로드","f5_title":"Git 타임머신, 브랜치 생성기 &amp; 컬러 통합 Diff 뷰어","f5_desc":"최대 120개의 커밋 히스토리를 탐색하며 모든 커밋의 2D 스크롤 +초록 / -빨강 통합 Diff를 확인하고, 로컬·원격 브랜치 생성 및 전환, 과거 스냅샷 안전 열람, 확인 절차가 포함된 하드 리셋을 수행합니다.","f5_badge":"통합 Diff 뷰어 · + 새 브랜치 · Detached HEAD 원탭 복구","f6_title":"다중 파일 비주얼 병합 충돌 해결기","f6_desc":"더 이상 &lt;&lt;&lt;&lt;&lt;&lt;&lt; 충돌 마커를 수동으로 지우지 마세요. 충돌 파일(1 / N)을 순서대로 넘기며 깔끔한 로컬 대 원격 비교 카드에서 현재 유지·수신 유지·둘 다 유지를 탭하면 자동 스테이징되어 즉시 커밋 및 푸시됩니다.","f6_badge":"현재 / 수신 / 둘 다 유지 · 자동 스테이징 큐","workflow_title":"완벽 6단계 가이드: SuperCode IDE에서 Git 사용하는 법","workflow_lead":"스마트폰이나 태블릿에서 클론, 브랜치 분기, 코드 비교, 충돌 병합, 원격 푸시까지 아래 순서대로 따라 해보세요.","wf_foot_note":"비정상 종료 후 남은 index.lock 자동 복구 · 인터넷 없는 오프라인 로컬 커밋 완벽 지원","wf1_title":"원격 저장소 클론 또는 로컬 프로젝트 마운트","wf1_desc":"HTTPS 주소(예: https://github.com/user/repo.git)와 선택적 PAT 토큰을 붙여넣고 클론을 탭하거나, 이미 .git 폴더가 있는 프로젝트라면 기존 저장소 마운트를 탭합니다.","wf2_title":"피처 브랜치 전환 또는 새 브랜치 생성","wf2_desc":"Git 타임머신을 열어 상단 브랜치 선택기로 브랜치를 바꾸거나, 브랜치명 유효성 검사가 적용된 + 새 브랜치 만들기…(예: feature/mobile-ui)를 탭합니다.","wf3_title":"전체 IDE 인텔리전스로 다중 파일 코드 수정","wf3_desc":"오프라인에서 코드를 수정·정렬·테스트하세요. 실수로 열린 탭 저장을 깜빡하더라도 Git 명령 실행 직전 변경된 탭이 디스크에 자동 저장됩니다.","wf4_title":"팀원의 원격 업데이트 안전하게 가져오기","wf4_desc":"푸시 전에 Pull을 탭하세요. 미커밋 로컬 수정본은 자동으로 Stash 후 복원되며, 열린 에디터 탭은 작업하던 커서 위치를 잃지 않고 즉시 갱신됩니다.","wf5_title":"겹치는 병합 충돌을 시각적 카드로 해결","wf5_desc":"동일 구간 수정 충돌이 발생하면 충돌 해결기 열기를 탭해 로컬 vs 원격 블록을 비교한 뒤 현재 유지 / 수신 유지 / 둘 다 유지를 선택하고 해결 적용을 누릅니다.","wf6_title":"대기 중인 파일 점검, 커밋 메시지 작성 &amp; 푸시","wf6_desc":"대기 중인 변경 목록에서 [M]/[A]/[D] 배지를 확인하고 작성자 정보와 커밋 메시지를 입력한 뒤 COMMIT을 탭해 스테이징·커밋·원격 origin 푸시를 완료합니다."},"sftp_client":{"metaTitle":"안드로이드 SFTP FTPS 에디터 — SSH 개인키 금고 & 무손실 원자적 원격 저장 | SuperCode","metaDesc":"안드로이드 SuperCode IDE에서 SFTP, FTPS(TLS 1.3), FTP 원격 서버에 직접 연결하세요. AES-256 보안 금고의 Ed25519/RSA/PEM SSH 키 인증, 3단계 원자적 원격 저장 코드 편집, 바이트 이어받기를 지원하는 안드로이드 SFTP FTPS 에디터입니다.","hero_tag":"SFTP · FTPS TLS 1.3 · FTP 원격 서버 워크스페이스","hero_h1":"무손실 원자적 저장으로 안전한 <span class=\"text-gradient\">SFTP, FTPS &amp; FTP<\/span> 실서버 코드 편집.","hero_desc":"클라우드 엔지니어, 시스템 관리자, 온콜 웹 개발자를 위한 안드로이드 SFTP FTPS 에디터입니다. <strong>AES-256 하드웨어 금고<\/strong>에 보호된 <strong>Ed25519/RSA/PEM 개인키<\/strong>로 <strong>SFTP(SSH 22), FTPS Explicit/Implicit(TLS 1.3), FTP<\/strong>에 접속하고, <strong>0바이트 손상 없는 원자적 원격 저장<\/strong>으로 운영 서버를 안전하게 수정하세요.","table_h2":"SuperCode SFTP / FTPS 워크스페이스 vs 별도 파일 전송 앱","snippet_p":"<strong>SuperCode 안드로이드 SFTP &amp; FTPS 클라이언트<\/strong>는 SFTP(SSH), Explicit/Implicit FTPS(TLS 1.3), FTP를 통합 지원하는 원격 서버 전용 코드 에디터입니다. Android KeyStore AES-256 SSH 키 금고, TOFU 지문 검증, 3단계 원자적 원격 저장과 4스트림 바이트 이어받기 전송 큐를 결합했습니다.","table_caption":"안드로이드 SFTP / FTPS 원격 코드 편집 환경 비교","faq_lead":"AWS/VPS용 SSH 개인키(.pem / Ed25519), FTPS TLS 1.3 지원, 원격 저장 시 0바이트 파일 손상 방지 및 대용량 이어받기 FAQ입니다.","cta_h2":"안드로이드에서 운영 VPS와 웹 호스팅 서버를 안심하고 관리하세요.","cta_desc":"Google Play에서 SuperCode IDE를 설치하고 AES-256 SFTP/FTPS 원격 편집, SSH 개인키 인증, 3단계 원자적 배포를 활용하세요.","th_0":"원격 서버 역량","th_1":"SuperCode SFTP/FTPS 스튜디오","th_2":"단독 FTP 파일 전송 앱","th_3":"기본 에디터 원격 플러그인","tr1_c0":"지원 프로토콜","tr1_c1":"SFTP(22) + FTPS Explicit TLS 1.3 + FTPS 990 + FTP","tr1_c2":"파일 전송 전용 (코드 IDE 없음)","tr1_c3":"기초 FTP/SFTP 일부만 지원","tr2_c0":"SSH 키 보안 &amp; MITM 방어","tr2_c1":"Ed25519/RSA/PEM + AES-256 KeyStore + TOFU SHA256","tr2_c2":"보안 수준 상이 / AST 에디터 없음","tr2_c3":"평문 설정 저장 또는 구형 키만 지원","tr3_c0":"통신 끊김 시 저장 안전성","tr3_c1":"3단계 원자적 저장 + 리눅스 POSIX 권한 보존","tr3_c2":"수동 다운로드 후 재업로드 번거로움","tr3_c3":"직접 덮어쓰기로 0바이트 손상 위험","tr4_c0":"중단된 대용량 전송","tr4_c1":"4개 병렬 스트림 + 정확한 바이트 오프셋 이어받기","tr4_c2":"일부 유료 앱만 지원","tr4_c3":"0%부터 처음부터 재전송","tr5_c0":"실시간 원격 웹 프리뷰","tr5_c1":"원탭 원격 HTML/CSS/JS/PHP 실시간 미리보기","tr5_c2":"미지원","tr5_c3":"미지원","faq1_q":"AWS EC2, DigitalOcean, 카페24나 일반 리눅스 VPS 접속 시 어떤 SSH 개인키 형식을 사용할 수 있나요?","faq1_a":"패스프레이즈 유무와 관계없이 OpenSSH, PEM(.pem), RSA(id_rsa), Ed25519(id_ed25519), ECDSA 개인키를 모두 지원하며, 다운로드 폴더와 .ssh 폴더로 바로 이동하는 전용 키 선택기가 내장되어 있습니다.","faq2_q":"원격 파일을 저장하는 도중 모바일 신호가 끊기면 서버 파일이 0바이트로 깨지지 않나요?","faq2_a":"절대 깨지지 않습니다. 모든 원격 탭 저장은 3단계 원자적 트랜잭션으로 동작하여 임시 파일에 먼저 업로드한 뒤 STAT/SIZE 명령으로 전체 바이트 도착 여부를 검증하고, 완전히 일치할 때만 리눅스 권한을 유지한 채 원본 파일 위로 원자적 이름 변경을 수행합니다.","faq3_q":"SSH 기반 SFTP 외에 SSL/TLS 암호화 방식인 FTPS도 지원하나요?","faq3_a":"네! 패시브 데이터 채널까지 암호화(PROT P)하는 21번 포트 Explicit FTPS(AUTH TLS 1.2/1.3)와 990번 포트 Implicit FTPS, 그리고 표준 UTF-8 패시브 FTP까지 모두 네이티브로 지원합니다.","faq4_q":"대용량 백업 파일을 다운로드하거나 업로드하다가 연결이 끊기면 이어받기가 가능한가요?","faq4_a":"네. 전송 대상 경로에 이미 일부 전송된 부분 파일이 감지되면 전송된 바이트 크기를 계산하여 완료된 구간을 다시 보낼 필요 없이 정확한 바이트 오프셋부터 원탭으로 부분 전송 이어받기를 수행합니다.","wb_eyebrow":"인터랙티브 SFTP 보안 금고, 원자적 저장 &amp; 병렬 전송 워크벤치","sec_cap_title":"엔터프라이즈급 원격 보안과 파일 손상 제로 엔지니어링","sec_cap_lead":"5G나 Wi-Fi 신호가 끊기는 순간 운영 서버 설정 파일을 0바이트 빈 파일로 날려버리는 일반 FTP 편집기의 치명적 약점을 근본적으로 해결했습니다.","f1_title":"4대 프로토콜 통합: SFTP, FTPS Explicit, FTPS Implicit &amp; FTP","f1_desc":"SSH 기반 SFTP(22번 포트), 암호화된 패시브 데이터 채널(PBSZ 0 + PROT P)을 사용하는 TLS 1.2/1.3 기반 Explicit FTPS, Implicit FTPS(990번 포트), 표준 UTF-8 패시브 FTP(21번 포트)를 모두 네이티브로 지원합니다.","f1_badge":"SFTP(22) · FTPS TLS 1.3(21) · FTPS(990) · FTP","f2_title":"SSH 개인키 선택기, AES-256 하드웨어 금고 &amp; TOFU 방어","f2_desc":"OpenSSH, PEM, RSA, Ed25519, ECDSA 개인키(.pem, .key, id_rsa, id_ed25519)와 패스프레이즈를 손쉽게 불러오세요. 모든 인증 비밀은 Android KeyStore AES-256-GCM으로 암호화되며 SHA256 호스트 지문 불일치 경고로 MITM 공격을 차단합니다.","f2_badge":"Ed25519 / RSA / PEM · AES-256-GCM · MITM 호스트 가드","f3_title":"3단계 원자적 원격 저장 (0바이트 파일 손상 원천 차단)","f3_desc":"원격 파일을 열면 영구 로컬 미러 탭(☁️)이 생성됩니다. 저장 시 임시 파일로 먼저 업로드한 뒤 STAT/SIZE로 원격 바이트 크기를 정확히 검증하고, 통과 시에만 원본 위로 원자적 이름 변경(Rename)을 수행하며 리눅스 POSIX 권한까지 그대로 보존합니다!","f3_badge":"임시 업로드 -&gt; 바이트 크기 검증 -&gt; 원자적 이름 변경 + chmod 보존","f4_title":"실시간 핸드셰이크 진단 콘솔 &amp; 자가 치유 연결 풀","f4_desc":"서버를 저장하기 전 내장 진단 콘솔에서 TCP 연결, TLS/SSH 협상, 키 인증 과정을 실시간으로 검증하세요. 3채널 멀티플렉싱 연결 풀이 Wi-Fi와 5G 네트워크 전환 후 끊어진 소켓을 자동으로 복구합니다.","f4_badge":"⚡ 핸드셰이크 진단 · 3채널 자가 치유 연결 풀","f5_title":"4스트림 병렬 전송 큐 &amp; 정확한 바이트 오프셋 이어받기","f5_desc":"전체 디렉터리 트리를 20fps 실시간 MB/s 속도 패널과 함께 4개 병렬 스트림으로 고속 업로드·다운로드합니다. 대용량 전송 중 연결이 끊겨도 SFTP RESUME 또는 FTP REST를 통해 중단된 정확한 바이트 지점부터 이어받습니다!","f5_badge":"4개 병렬 스트림 · 실시간 MB/s · 바이트 오프셋 이어받기","f6_title":"원격 퍼지 파일 검색 &amp; 원격 웹사이트 실시간 프리뷰","f6_desc":"원격 서버 디렉터리 전반에서 파일명을 빠르게 퍼지 검색하고 34종 인코딩으로 원격 탭을 다시 읽을 수 있으며, 원격 HTML/PHP 파일에서 실행을 눌러 수정 전후 실서버 웹페이지를 즉시 미리 확인할 수 있습니다.","f6_badge":"원격 퍼지 검색 · 34종 인코딩 · 실시간 원격 웹 프리뷰","workflow_title":"안드로이드에서 운영 서버에 안전하게 접속하고 핫픽스 배포하기","workflow_lead":"하드웨어 암호화 금고에 한 번만 등록해 두면 언제 어디서나 몇 초 만에 안전하게 원격 코드를 수정할 수 있습니다.","wf_foot_note":"원격 리눅스 POSIX 파일 권한 완벽 보존 · 앱 재시작 및 오프라인 전환 시에도 로컬 미러 탭 유지","wf1_title":"프로토콜 선택 및 비밀번호 또는 SSH 개인키 등록","wf1_desc":"SFTP, FTPS(TLS), FTPS(990), FTP 중 하나를 고르고 호스트·계정을 입력한 뒤 비밀번호나 .pem / id_ed25519 개인키 파일을 선택합니다.","wf2_title":"연결 진단 로그 확인 &amp; 호스트 지문 신뢰 등록","wf2_desc":"핸드셰이크 테스트를 탭해 TCP/TLS/SSH 인증 성공 여부를 실시간 확인하고 서버의 SHA256 호스트 지문을 검증한 뒤 AES-256 금고에 저장합니다.","wf3_title":"원격 폴더 트리 탐색 &amp; AST 자동완성·포매팅 편집","wf3_desc":"Nginx 설정, Python/PHP 백엔드 코드, 쉘 스크립트를 에디터 탭으로 바로 열어 AST 자동완성, 에러 레이더, 원탭 코드 정렬로 편집합니다.","wf4_title":"3단계 원자적 저장 배포 또는 충돌 정책 기반 폴더 동기화","wf4_desc":"저장을 탭해 3단계 원자적 배포를 수행하거나, 여러 폴더를 다중 선택해 덮어쓰기·바이트 이어받기·둘 다 유지·건너뛰기 정책으로 전송합니다."}};
